PathwayData.put("data/reading_writing/units/L01U1.json",{"strand":"reading_writing","level":1,"cefr":"A1a","unit":1,"theme":"All About Me","essential_question":"Who am I, and what makes me special?","schema_version":"1.0","core_words":["name","boy","girl","friend","happy","big","small","eye","hand","hair","age","like","school","me"],"recycled_words":[],"rubrics":[{"id":"RW-RUBRIC-5T","title":"Analytic writing rubric","traits":[{"name":"Ideas","name_ar":"الأفكار","bands":[{"score":4,"descriptor":"My ideas are clear, interesting and fully developed with strong details.","descriptor_ar":"أفكاري واضحة وممتعة ومدعومة بتفاصيل قوية."},{"score":3,"descriptor":"My ideas are clear and have enough details.","descriptor_ar":"أفكاري واضحة ومعها تفاصيل كافية."},{"score":2,"descriptor":"My main idea is there but needs more details.","descriptor_ar":"فكرتي الرئيسية موجودة لكنها تحتاج إلى تفاصيل أكثر."},{"score":1,"descriptor":"My ideas are unclear or very few.","descriptor_ar":"أفكاري غير واضحة أو قليلة جدًا."}]},{"name":"Organization","name_ar":"التنظيم","bands":[{"score":4,"descriptor":"Clear beginning, middle and end; ideas flow with linking words.","descriptor_ar":"بداية ووسط ونهاية واضحة، والأفكار مترابطة بكلمات الربط."},{"score":3,"descriptor":"Clear order with some linking words.","descriptor_ar":"ترتيب واضح مع بعض كلمات الربط."},{"score":2,"descriptor":"Some order, but parts are mixed up.","descriptor_ar":"يوجد بعض الترتيب لكن بعض الأجزاء غير مرتبة."},{"score":1,"descriptor":"Ideas are not in order.","descriptor_ar":"الأفكار غير مرتبة."}]},{"name":"Vocabulary","name_ar":"المفردات","bands":[{"score":4,"descriptor":"I use exact, varied words, including new unit words, correctly.","descriptor_ar":"أستخدم كلمات دقيقة ومتنوعة، منها كلمات الوحدة الجديدة، بشكل صحيح."},{"score":3,"descriptor":"I use some new words correctly.","descriptor_ar":"أستخدم بعض الكلمات الجديدة بشكل صحيح."},{"score":2,"descriptor":"I use simple words; some are repeated or wrong.","descriptor_ar":"أستخدم كلمات بسيطة، وبعضها مكرر أو غير صحيح."},{"score":1,"descriptor":"I use very few words; the meaning is hard to understand.","descriptor_ar":"أستخدم كلمات قليلة جدًا ويصعب فهم المعنى."}]},{"name":"Sentence fluency","name_ar":"سلاسة الجمل","bands":[{"score":4,"descriptor":"My sentences are complete, varied in length and easy to read aloud.","descriptor_ar":"جملي كاملة ومتنوعة الطول وسهلة القراءة بصوت عالٍ."},{"score":3,"descriptor":"Most sentences are complete, with some variety.","descriptor_ar":"معظم جملي كاملة مع بعض التنويع."},{"score":2,"descriptor":"Many sentences are short or start the same way.","descriptor_ar":"كثير من جملي قصيرة أو تبدأ بالطريقة نفسها."},{"score":1,"descriptor":"Sentences are incomplete or run together.","descriptor_ar":"جملي ناقصة أو متداخلة."}]},{"name":"Conventions","name_ar":"قواعد الكتابة","bands":[{"score":4,"descriptor":"Capitals, punctuation, spelling and grammar are almost always correct.","descriptor_ar":"الحروف الكبيرة وعلامات الترقيم والإملاء والقواعد صحيحة دائمًا تقريبًا."},{"score":3,"descriptor":"A few mistakes that do not affect meaning.","descriptor_ar":"أخطاء قليلة لا تؤثر في المعنى."},{"score":2,"descriptor":"Several mistakes; the meaning is sometimes unclear.","descriptor_ar":"عدة أخطاء، والمعنى أحيانًا غير واضح."},{"score":1,"descriptor":"Many mistakes make it hard to read.","descriptor_ar":"أخطاء كثيرة تجعل القراءة صعبة."}]}]}],"lessons":[{"id":"RW-L01-U1-LS1","title":"Word Power: All About Me","lesson_type":"vocabulary","objectives":["read and say 14 core words about themselves (name, boy, girl, friend, happy, big, small, eye, hand, hair, age, like, school, me) and 2 Tier 2 words (favorite, special)","use picture clues and labels to work out what a new word means","use the new words in short spoken and written sentences about themselves"],"objectives_ar":["قراءة ونطق 14 كلمة أساسية عن أنفسهم وكلمتين أكاديميتين (favorite, special).","استخدام أدلة الصورة والبطاقات التعريفية لمعرفة معنى الكلمة الجديدة.","استخدام الكلمات الجديدة في جمل قصيرة منطوقة ومكتوبة عن أنفسهم."],"success_criteria":["I can read and say the new words.","I can use a picture and a label to find what a word means.","I can use the words to talk and write about me."],"success_criteria_ar":["أستطيع قراءة الكلمات الجديدة ونطقها.","أستطيع استخدام الصورة والبطاقة لمعرفة معنى الكلمة.","أستطيع استخدام الكلمات للتحدث والكتابة عن نفسي."],"map_area":"Vocabulary: Acquisition and Use","vocabulary":[{"word":"name","pos":"noun","ipa":"/neɪm/","definition":"the word people call you","arabic":"اسم","example":"Her name is Noura.","image_id":"IMG-RW-L01-U1-LS1-V01","audio_id":"AUD-RW-L01-U1-LS1-V01","tier":"core"},{"word":"boy","pos":"noun","ipa":"/bɔɪ/","definition":"a young male child","arabic":"ولد","example":"The boy has a red bag.","image_id":"IMG-RW-L01-U1-LS1-V02","audio_id":"AUD-RW-L01-U1-LS1-V02","tier":"core"},{"word":"girl","pos":"noun","ipa":"/ɡɝl/","definition":"a young female child","arabic":"بنت","example":"The girl has a blue pen.","image_id":"IMG-RW-L01-U1-LS1-V03","audio_id":"AUD-RW-L01-U1-LS1-V03","tier":"core"},{"word":"friend","pos":"noun","ipa":"/frɛnd/","definition":"a person you like and play with","arabic":"صديق","example":"Omar is a good friend.","image_id":"IMG-RW-L01-U1-LS1-V04","audio_id":"AUD-RW-L01-U1-LS1-V04","tier":"core"},{"word":"happy","pos":"adjective","ipa":"/ˈhæpi/","definition":"feeling good","arabic":"سعيد","example":"The baby is happy.","image_id":"IMG-RW-L01-U1-LS1-V05","audio_id":"AUD-RW-L01-U1-LS1-V05","tier":"core"},{"word":"big","pos":"adjective","ipa":"/bɪɡ/","definition":"large; not small","arabic":"كبير","example":"A camel is big.","image_id":"IMG-RW-L01-U1-LS1-V06","audio_id":"AUD-RW-L01-U1-LS1-V06","tier":"core"},{"word":"small","pos":"adjective","ipa":"/smɔl/","definition":"little; not big","arabic":"صغير","example":"A cat is small.","image_id":"IMG-RW-L01-U1-LS1-V07","audio_id":"AUD-RW-L01-U1-LS1-V07","tier":"core"},{"word":"eye","pos":"noun","ipa":"/aɪ/","definition":"the part of your face you see with","arabic":"عين","example":"Close your eyes.","image_id":"IMG-RW-L01-U1-LS1-V08","audio_id":"AUD-RW-L01-U1-LS1-V08","tier":"core"},{"word":"hand","pos":"noun","ipa":"/hænd/","definition":"the part at the end of your arm","arabic":"يد","example":"Wash your hands.","image_id":"IMG-RW-L01-U1-LS1-V09","audio_id":"AUD-RW-L01-U1-LS1-V09","tier":"core"},{"word":"hair","pos":"noun","ipa":"/hɛr/","definition":"it grows on your head","arabic":"شَعر","example":"His hair is black.","image_id":"IMG-RW-L01-U1-LS1-V10","audio_id":"AUD-RW-L01-U1-LS1-V10","tier":"core"},{"word":"age","pos":"noun","ipa":"/eɪdʒ/","definition":"how old you are","arabic":"العُمر","example":"Omar's age is nine.","image_id":"IMG-RW-L01-U1-LS1-V11","audio_id":"AUD-RW-L01-U1-LS1-V11","tier":"core"},{"word":"like","pos":"verb","ipa":"/laɪk/","definition":"to enjoy something","arabic":"يُحِبّ","example":"I like apples.","image_id":"IMG-RW-L01-U1-LS1-V12","audio_id":"AUD-RW-L01-U1-LS1-V12","tier":"core"},{"word":"school","pos":"noun","ipa":"/skul/","definition":"the place where children learn","arabic":"مدرسة","example":"My school is near my house.","image_id":"IMG-RW-L01-U1-LS1-V13","audio_id":"AUD-RW-L01-U1-LS1-V13","tier":"core"},{"word":"me","pos":"pronoun","ipa":"/mi/","definition":"the word you use for yourself","arabic":"أنا / ـني","example":"Look at me!","image_id":"IMG-RW-L01-U1-LS1-V14","audio_id":"AUD-RW-L01-U1-LS1-V14","tier":"core"},{"word":"favorite","pos":"adjective","ipa":"/ˈfeɪvərɪt/","definition":"the one you like the most","arabic":"المُفضَّل","example":"Blue is my favorite color.","image_id":"IMG-RW-L01-U1-LS1-V15","audio_id":"AUD-RW-L01-U1-LS1-V15","tier":"tier2"},{"word":"special","pos":"adjective","ipa":"/ˈspɛʃəl/","definition":"different and important","arabic":"مُمَيَّز","example":"Every child is special.","image_id":"IMG-RW-L01-U1-LS1-V16","audio_id":"AUD-RW-L01-U1-LS1-V16","tier":"tier2"}],"explanation":{"text":"A **picture** can help you read a new word. Look at the picture first. Then read the word.\n\nA **label** is a word next to a part of a picture. A line or an arrow goes from the label to the part. The label tells you the name of that part.\n\nDo this: **1. Look** at the picture. **2. Point** to the part. **3. Read** the label. **4. Say** the word in a sentence.","examples":["Picture: a boy with a big smile. Label: **happy**. → Happy means feeling good.","Picture: a face. A line goes to the eye. Label: **eye**. → I see with my eyes.","Picture: a big camel and a small cat. Labels: **big**, **small**. → The camel is big. The cat is small.","Picture: a boy. Arrow to his head. Label: **hair**. → His hair is short.","Picture: two girls playing. Label: **friend**. → Noura is my friend.","Picture: a building with children. Label: **school**. → I go to school.","Picture: a cake with eight candles. Label: **age**. → My age is eight.","Picture: a child pointing to herself. Label: **me**. → This is me!","Picture: a red ball with a heart. Label: **favorite**. → Red is my favorite color."],"common_errors":["✗ I have 8 years. → ✓ I am eight years old. (In Arabic we say عمري ٨ سنوات; in English we use **am**.)","✗ Me name is Sami. → ✓ My name is Sami. (Use **my** before a noun.)","✗ My hair are black. → ✓ My hair is black. (**Hair** is one thing in English.)","✗ I like play football. → ✓ I like football. (Do not put two verbs together like this.)","✗ a eye → ✓ an eye (Use **an** before a, e, i, o, u sounds.)","✗ He is a good friend for me. → ✓ He is my good friend. (Use **my** for your friend.)","✗ Look at picture. → ✓ Look at the picture. (In Arabic the word الـ is joined; in English **the** is a separate word.)"],"arabic":"عندما ترى كلمة جديدة، انظر إلى الصورة أولًا. الصورة تساعدك على فهم الكلمة.\n\nالبطاقة (label) كلمة مكتوبة بجانب جزء من الصورة، ويخرج منها خط أو سهم إلى ذلك الجزء. البطاقة تخبرك باسم هذا الجزء.\n\nالخطوات: انظر إلى الصورة – أشِر إلى الجزء – اقرأ البطاقة – قل الكلمة في جملة.\n\nانتبه: نقول بالإنجليزية I am eight years old ولا نقول I have 8 years."},"video":{"script":[{"time":"00:00–00:15","narration":"Hello, friends! I am Saqr. Today we learn words about YOU!","on_screen":"Words About Me","visual":"Saqr the falcon flies in and lands on a pencil; title appears letter by letter."},{"time":"00:15–00:40","narration":"Look at the picture. This is Sami. Sami is a boy. Say: boy.","on_screen":"boy","visual":"Sami waves; the label 'boy' slides in with an arrow to Sami. Pause 2 seconds."},{"time":"00:40–01:05","narration":"Look! A line goes from the label to the eye. The label says: eye. Say: eye. Now hand. Now hair.","on_screen":"eye · hand · hair","visual":"Labels appear one by one with arrows to Sami's eye, hand and hair; each glows as it is read."},{"time":"01:05–01:30","narration":"Big or small? The camel is big. The cat is small. Say: big. Say: small.","on_screen":"big / small","visual":"A big camel walks in from the left, a small cat from the right; size arrows grow and shrink."},{"time":"01:30–01:55","narration":"This is Noura. Noura is a girl. Noura is Sami's friend. They are happy!","on_screen":"girl · friend · happy","visual":"Noura joins Sami; both smile; hearts and stars pop gently above them."},{"time":"01:55–02:15","narration":"Picture, point, read, say! Look, point, read the label, and say the word.","on_screen":"1 Look  2 Point  3 Read  4 Say","visual":"Four big icons light up in order: eye, finger, book, speech bubble."},{"time":"02:15–02:30","narration":"You are special. Now say: This is me!","on_screen":"This is me!","visual":"Saqr holds up a mirror frame; the viewer's 'reflection' outline appears with a star."}],"captions_ar":["مرحبًا يا أصدقاء! أنا صقر. اليوم نتعلم كلمات عنكم!","انظروا إلى الصورة. هذا سامي. سامي ولد. قولوا: boy.","انظروا! خط يخرج من البطاقة إلى العين. البطاقة تقول: eye. والآن يد، والآن شعر.","كبير أم صغير؟ الجمل كبير. القطة صغيرة.","هذه نورة. نورة بنت. نورة صديقة سامي. هما سعيدان!","انظر، أشِر، اقرأ، قل! انظر إلى الصورة وأشِر واقرأ البطاقة وقل الكلمة.","أنت مميز. والآن قل: هذا أنا!"],"voice":"American English, warm female teacher voice for the narrator; a light, playful young male voice for Saqr the falcon. Speed 0.8, clear pauses after each new word, friendly and slow. Children repeat in the pauses."},"texts":[],"activities":[{"id":"RW-L01-U1-LS1-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read and choose the correct word.","instructions_ar":"اقرأ واختر الكلمة الصحيحة.","items":[{"q":"Which word means *feeling good*?","answer":"happy","explanation":"Happy means feeling good.","explanation_ar":"happy تعني سعيد.","options":["small","hair","happy","school"],"dok":1,"skill":"word meaning","stage":"controlled"},{"q":"The part of your face you see with is your ___.","answer":"eye","explanation":"We see with our eyes.","explanation_ar":"نرى بأعيننا.","options":["hand","eye","hair","name"],"dok":1,"skill":"word meaning","stage":"controlled"},{"q":"A camel is ___.","answer":"big","explanation":"A camel is a large animal.","explanation_ar":"الجمل حيوان كبير.","options":["big","small","happy","special"],"dok":1,"skill":"word meaning","stage":"controlled"},{"q":"A young female child is a ___.","answer":"girl","explanation":"A girl is a young female child.","explanation_ar":"girl تعني بنت.","options":["boy","friend","school","girl"],"dok":1,"skill":"word meaning","stage":"controlled"},{"q":"Children learn at ___.","answer":"school","explanation":"School is where children learn.","explanation_ar":"المدرسة مكان التعلم.","options":["hair","school","age","eye"],"dok":1,"skill":"word meaning","stage":"controlled"},{"q":"You write and wash with your ___.","answer":"hands","explanation":"We use our hands to write and wash.","explanation_ar":"نستخدم أيدينا للكتابة والغسل.","options":["eyes","hair","names","hands"],"dok":1,"skill":"word meaning","stage":"controlled"}]},{"id":"RW-L01-U1-LS1-A2","type":"gap_fill","stage":"guided","instructions":"Guided practice: Use the word bank to complete each sentence.","instructions_ar":"استخدم بنك الكلمات لإكمال كل جملة.","items":[{"q":"My ________ is Sami.","answer":"name","explanation":"We say our name with *My name is…*","explanation_ar":"نقول اسمنا بعبارة My name is.","stage":"guided"},{"q":"Omar is my good ________.","answer":"friend","explanation":"A friend is a person you like and play with.","explanation_ar":"الصديق شخص تحبه وتلعب معه.","stage":"guided"},{"q":"A kitten is ________.","answer":"small","explanation":"A kitten is little.","explanation_ar":"القطة الصغيرة حجمها صغير.","stage":"guided"},{"q":"Noura's ________ is long and black.","answer":"hair","explanation":"Hair grows on your head.","explanation_ar":"الشعر ينمو على الرأس.","stage":"guided"},{"q":"I ________ apples and dates.","answer":"like","explanation":"Like means to enjoy something.","explanation_ar":"like تعني يحب.","stage":"guided"},{"q":"My ________ is eight. I am eight years old.","answer":"age","explanation":"Age is how old you are.","explanation_ar":"العمر هو عدد سنوات حياتك.","stage":"guided"}]},{"id":"RW-L01-U1-LS1-A3","type":"open","stage":"freer","instructions":"Freer practice: Complete the sentences about YOU.","instructions_ar":"أكمل الجمل عن نفسك.","items":[{"q":"My name is ______.","answer":"My name is Ali.","explanation":"Any real name with a capital letter.","explanation_ar":"أي اسم حقيقي يبدأ بحرف كبير.","dok":1,"skill":"personal response","stage":"freer"},{"q":"I am a ______. (boy / girl)","answer":"I am a boy.","explanation":"Choose the true word.","explanation_ar":"اختر الكلمة الصحيحة عنك.","dok":1,"skill":"personal response","stage":"freer"},{"q":"My favorite color is ______.","answer":"My favorite color is green.","explanation":"Any color word.","explanation_ar":"أي اسم لون.","dok":2,"skill":"personal response","stage":"freer"},{"q":"I like ______.","answer":"I like football.","explanation":"Any thing you enjoy.","explanation_ar":"أي شيء تحبه.","dok":2,"skill":"personal response","stage":"freer"}]},{"id":"RW-L01-U1-LS1-A4","type":"open","stage":"production","instructions":"Writing: Draw yourself in the box. Write a label for each part. Then write one sentence.","instructions_ar":"ارسم نفسك في المربع، واكتب بطاقة لكل جزء، ثم اكتب جملة واحدة.","items":[{"q":"Draw a line to your eyes. Write the label.","answer":"eyes","explanation":"Label points to the eyes.","explanation_ar":"البطاقة تشير إلى العينين.","dok":1,"skill":"labelling","stage":"production"},{"q":"Draw a line to your hair. Write the label.","answer":"hair","explanation":"Label points to the hair.","explanation_ar":"البطاقة تشير إلى الشعر.","dok":1,"skill":"labelling","stage":"production"},{"q":"Draw a line to your hands. Write the label.","answer":"hands","explanation":"Label points to the hands.","explanation_ar":"البطاقة تشير إلى اليدين.","dok":1,"skill":"labelling","stage":"production"},{"q":"Write one sentence about your picture. Use *happy*, *big* or *small*.","answer":"I am happy.","explanation":"A full sentence with one of the words.","explanation_ar":"جملة كاملة فيها إحدى الكلمات.","dok":2,"skill":"sentence writing","stage":"production"}]}],"game":{"name":"Label Dash","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Drag-and-drop: labels fall from the top of the screen; the child drags each label to the right part of Sami's picture. Correct = green glow + word audio; wrong = gentle shake and the label returns. 60-second timer; stars for speed.","Make two teams. Each team stands in a line 3 meters from its poster.","The teacher says a word, e.g., \"hair!\"","The first student in each line finds the label, runs to the poster, sticks it on the right part and says the word.","Correct label and word = 1 point. The student goes to the back of the line.","After 8 words, the team with more points wins. Both teams read all labels together at the end."],"data":[]},"exit_quiz":[{"q":"Which word is a part of your face?","answer":"eye","explanation":"The eye is on your face.","explanation_ar":"العين جزء من الوجه.","options":["school","age","friend","eye"],"dok":1,"skill":"vocabulary"},{"q":"Which word is the opposite of *big*?","answer":"small","explanation":"Small is the opposite of big.","explanation_ar":"small عكس big.","options":["small","happy","special","girl"],"dok":1,"skill":"vocabulary"},{"q":"Omar plays with me. He is my ___.","answer":"friend","explanation":"A person you play with is a friend.","explanation_ar":"الشخص الذي تلعب معه صديق.","options":["hair","hand","friend","age"],"dok":1,"skill":"vocabulary"},{"q":"What word goes with this picture: a cake with nine candles?","answer":"age","explanation":"Candles on a cake show your age.","explanation_ar":"الشموع على الكعكة تدل على العمر.","options":["eye","hand","boy","age"],"dok":2,"skill":"picture clue"},{"q":"I see a smiling baby. The baby is ___.","answer":"happy","explanation":"A smile shows the baby feels good.","explanation_ar":"الابتسامة تدل على السعادة.","options":["small","special","happy","school"],"dok":2,"skill":"picture clue"},{"q":"A label is a word that ___.","answer":"names a part of a picture","explanation":"A label names a part of a picture.","explanation_ar":"البطاقة تسمّي جزءًا من الصورة.","options":["names a part of a picture","tells a long story","is always a color","is a number"],"dok":1,"skill":"strategy"},{"q":"Which sentence about age is correct?","answer":"I am eight years old.","explanation":"In English we say *I am … years old*.","explanation_ar":"نقول I am eight years old.","options":["I have eight years.","I am eight years old.","I eight years.","Me eight years old."],"dok":2,"skill":"usage"},{"q":"Red is the color I like the most. Red is my ___ color.","answer":"favorite","explanation":"Favorite means the one you like the most.","explanation_ar":"favorite تعني المفضل.","options":["favorite","small","happy","big"],"dok":2,"skill":"vocabulary"},{"q":"Which word can finish the sentence: *Look at ___!*","answer":"me","explanation":"We say *Look at me!*","explanation_ar":"نقول Look at me.","options":["age","me","big","happy"],"dok":2,"skill":"usage"},{"q":"Every child is different and important. Every child is ___.","answer":"special","explanation":"Special means different and important.","explanation_ar":"special تعني مميز.","options":["small","hair","special","school"],"dok":3,"skill":"vocabulary in context"}],"images":[{"id":"IMG-RW-L01-U1-LS1-V01","prompt":"Picture for the word 'name': a smiling girl pointing to a blank name sticker on her school bag"},{"id":"IMG-RW-L01-U1-LS1-V02","prompt":"Picture for the word 'boy': Sami waving, wearing a navy school polo"},{"id":"IMG-RW-L01-U1-LS1-V03","prompt":"Picture for the word 'girl': Noura with a braid and headband holding a blue pen"},{"id":"IMG-RW-L01-U1-LS1-V04","prompt":"Picture for the word 'friend': two boys laughing together on a school bench"},{"id":"IMG-RW-L01-U1-LS1-V05","prompt":"Picture for the word 'happy': a laughing baby clapping"},{"id":"IMG-RW-L01-U1-LS1-V06","prompt":"Picture for the word 'big': a large camel standing next to a small cat for size"},{"id":"IMG-RW-L01-U1-LS1-V07","prompt":"Picture for the word 'small': a tiny kitten sitting in a child's hands"},{"id":"IMG-RW-L01-U1-LS1-V08","prompt":"Picture for the word 'eye': a close-up of a child's face with one eye winking"},{"id":"IMG-RW-L01-U1-LS1-V09","prompt":"Picture for the word 'hand': a child's hands under a running tap with soap"},{"id":"IMG-RW-L01-U1-LS1-V10","prompt":"Picture for the word 'hair': a boy with short black curly hair, side view"},{"id":"IMG-RW-L01-U1-LS1-V11","prompt":"Picture for the word 'age': a birthday cake with nine candles, no text"},{"id":"IMG-RW-L01-U1-LS1-V12","prompt":"Picture for the word 'like': a child smiling and giving a thumbs-up to a red apple"},{"id":"IMG-RW-L01-U1-LS1-V13","prompt":"Picture for the word 'school': a bright Saudi school building with palm trees and a flag pole"},{"id":"IMG-RW-L01-U1-LS1-V14","prompt":"Picture for the word 'me': a child pointing to himself with a big smile"},{"id":"IMG-RW-L01-U1-LS1-V15","prompt":"Picture for the word 'favorite': a child hugging a blue ball among other colored balls"},{"id":"IMG-RW-L01-U1-LS1-V16","prompt":"Picture for the word 'special': a row of different children, one in front glowing softly with a star above"},{"id":"IMG-RW-L01-U1-LS1-01","prompt":"Sami and Noura wave hello in their classroom; Saqr the falcon sits on the window."},{"id":"IMG-RW-L01-U1-LS1-02","prompt":"Sami standing and smiling, with space around him for labels."},{"id":"IMG-RW-L01-U1-LS1-03","prompt":"Saqr the falcon lands on a big pencil."}],"audio":[{"id":"AUD-RW-L01-U1-LS1-V01","script":"name. Her name is Noura."},{"id":"AUD-RW-L01-U1-LS1-V02","script":"boy. The boy has a red bag."},{"id":"AUD-RW-L01-U1-LS1-V03","script":"girl. The girl has a blue pen."},{"id":"AUD-RW-L01-U1-LS1-V04","script":"friend. Omar is a good friend."},{"id":"AUD-RW-L01-U1-LS1-V05","script":"happy. The baby is happy."},{"id":"AUD-RW-L01-U1-LS1-V06","script":"big. A camel is big."},{"id":"AUD-RW-L01-U1-LS1-V07","script":"small. A cat is small."},{"id":"AUD-RW-L01-U1-LS1-V08","script":"eye. Close your eyes."},{"id":"AUD-RW-L01-U1-LS1-V09","script":"hand. Wash your hands."},{"id":"AUD-RW-L01-U1-LS1-V10","script":"hair. His hair is black."},{"id":"AUD-RW-L01-U1-LS1-V11","script":"age. Omar's age is nine."},{"id":"AUD-RW-L01-U1-LS1-V12","script":"like. I like apples."},{"id":"AUD-RW-L01-U1-LS1-V13","script":"school. My school is near my house."},{"id":"AUD-RW-L01-U1-LS1-V14","script":"me. Look at me!"},{"id":"AUD-RW-L01-U1-LS1-V15","script":"favorite. Blue is my favorite color."},{"id":"AUD-RW-L01-U1-LS1-V16","script":"special. Every child is special."},{"id":"AUD-RW-L01-U1-LS1-VID","script":"Hello, friends! I am Saqr. Today we learn words about YOU! Look at the picture. This is Sami. Sami is a boy. Say: boy. Look! A line goes from the label to the eye. The label says: eye. Say: eye. Now hand. Now hair. Big or small? The camel is big. The cat is small. Say: big. Say: small. This is Noura. Noura is a girl. Noura is Sami's friend. They are happy! Picture, point, read, say! Look, point, read the label, and say the word. You are special. Now say: This is me!"}]},{"id":"RW-L01-U1-LS2","title":"Hello, I Am Sami","lesson_type":"close_reading","objectives":["read a short personal story (85 words) with support and answer who, what and where questions","find the sentence in the text that answers a question (evidence)","use clues to answer a \"think\" question and give a personal \"me\" answer"],"objectives_ar":["قراءة قصة شخصية قصيرة (85 كلمة) بدعم والإجابة عن أسئلة من وماذا وأين.","إيجاد الجملة في النص التي تجيب عن السؤال (الدليل).","استخدام الأدلة للإجابة عن سؤال تفكير، وإعطاء إجابة شخصية."],"success_criteria":["I can read the story about Sami.","I can find the answer right there in the story.","I can use clues to think and say what I think."],"success_criteria_ar":["أستطيع قراءة القصة عن سامي.","أستطيع إيجاد الإجابة مكتوبة في القصة.","أستطيع استخدام الأدلة لأفكر وأقول رأيي."],"map_area":"Literary Text: Key Ideas and Details","vocabulary":[{"word":"years old","pos":"phrase","ipa":"/jɪrz oʊld/","definition":"words we use to say our age","arabic":"من العمر","example":"My sister is five years old.","image_id":"IMG-RW-L01-U1-LS2-V01","audio_id":"AUD-RW-L01-U1-LS2-V01","tier":"core"},{"word":"short","pos":"adjective","ipa":"/ʃɔrt/","definition":"not long","arabic":"قصير","example":"The pencil is short.","image_id":"IMG-RW-L01-U1-LS2-V02","audio_id":"AUD-RW-L01-U1-LS2-V02","tier":"core"},{"word":"tall","pos":"adjective","ipa":"/tɔl/","definition":"high from head to feet","arabic":"طويل القامة","example":"My father is tall.","image_id":"IMG-RW-L01-U1-LS2-V03","audio_id":"AUD-RW-L01-U1-LS2-V03","tier":"core"},{"word":"smile","pos":"noun","ipa":"/smaɪl/","definition":"a happy face with your mouth","arabic":"ابتسامة","example":"Grandpa has a kind smile.","image_id":"IMG-RW-L01-U1-LS2-V04","audio_id":"AUD-RW-L01-U1-LS2-V04","tier":"core"},{"word":"ask","pos":"verb","ipa":"/æsk/","definition":"to say a question","arabic":"يسأل","example":"I ask my teacher a question.","image_id":"IMG-RW-L01-U1-LS2-V05","audio_id":"AUD-RW-L01-U1-LS2-V05","tier":"core"},{"word":"first","pos":"adjective","ipa":"/fɝst/","definition":"number one; before all the others","arabic":"الأول","example":"Ali is first in the line.","image_id":"IMG-RW-L01-U1-LS2-V06","audio_id":"AUD-RW-L01-U1-LS2-V06","tier":"core"},{"word":"new","pos":"adjective","ipa":"/nu/","definition":"not old; you did not have it before","arabic":"جديد","example":"I have a new bag.","image_id":"IMG-RW-L01-U1-LS2-V07","audio_id":"AUD-RW-L01-U1-LS2-V07","tier":"core"}],"explanation":{"text":"When we read a story, we answer questions. There are **three kinds** of questions.\n\n**Right There** questions: the answer is in the story. Find the sentence and point to it.\n\n**Think** questions: the answer is not in one sentence. Use clues in the story and think.\n\n**Me** questions: the answer is about YOU. Say what you think and why.","examples":["Right There: *How old is Sami?* → \"I am eight years old.\"","Right There: *What color are Sami's eyes?* → \"brown eyes\"","Right There: *Who is Sami's friend?* → \"My friend is Omar.\"","Right There: *Where is Sami's school?* → \"in Taif\"","Think: *Is Sami a new student in the class?* → Yes. Clue: \"my first day in a new class\".","Think: *Does Sami like to learn?* → Yes. Clues: he likes books; he asks \"Why?\"","Think: *How does Sami feel?* → Happy. Clue: \"I am happy.\" and \"my smile is big\".","Me: *Do you like books like Sami?* → Yes, I like books. / No, I like football.","Me: *What do you ask at school?* → I ask, \"What is this?\""],"common_errors":["✗ Sami have black hair. → ✓ Sami has black hair. (With he/she/a name, use **has**.)","✗ Omar like football. → ✓ Omar likes football. (With he/she, add **-s** to the verb.)","✗ Noura is my friend. He is nice. → ✓ Noura is my friend. She is nice. (Use **she** for a girl.)","✗ Sami is eight years. → ✓ Sami is eight years old. (Say **years old** at the end.)","✗ Answer: Taif. → ✓ His school is in Taif. (In a full answer, use a whole sentence.)","✗ I am happy because first day. → ✓ I am happy because it is my first day. (After **because**, use a full sentence.)"],"arabic":"هناك ثلاثة أنواع من الأسئلة عند قراءة القصة:\n\nسؤال \"الإجابة هنا\" (Right There): الإجابة مكتوبة في القصة؛ ابحث عن الجملة وأشر إليها.\n\nسؤال \"فكِّر\" (Think): الإجابة ليست في جملة واحدة؛ استخدم الأدلة وفكِّر.\n\nسؤال \"أنا\" (Me): الإجابة عنك أنت؛ قل رأيك ولماذا.\n\nانتبه: نقول Sami has ولا نقول Sami have، ونقول Omar likes بإضافة s."},"video":{"script":[{"time":"00:00–00:20","narration":"Sami has a story for you. Listen and look.","on_screen":"Hello, I Am Sami","visual":"Sami waves from the doorway of a bright classroom; the title pops up on the board."},{"time":"00:20–01:05","narration":"Hello! My name is Sami. I am a boy. I am eight years old. I have short black hair and brown eyes…","on_screen":"(the story text, sentence by sentence)","visual":"Each sentence appears and is highlighted word by word as Sami reads; small pictures appear: number 8, hair, eyes, hands, Omar with a football, a book, the moon."},{"time":"01:05–01:30","narration":"Right There questions! The answer is in the story. How old is Sami? Look… eight years old!","on_screen":"Right There 👉","visual":"A magnifying glass moves over the text and stops on 'eight years old', which glows."},{"time":"01:30–02:00","narration":"Think questions! Is Sami new in the class? Find a clue… 'my first day in a new class'. Yes, he is new!","on_screen":"Think 🧠 + clue","visual":"Saqr puts on a detective hat; the clue sentence lights up; a thought bubble shows 'new'."},{"time":"02:00–02:25","narration":"Me questions! Do YOU like books like Sami? Say: Yes, I like books. Or: No, I like football.","on_screen":"Me 🙋","visual":"A mirror frame turns to the viewer; two speech bubbles show the two answers."},{"time":"02:25–02:40","narration":"Right There, Think, Me! Now you read the story.","on_screen":"Right There · Think · Me","visual":"Three icons line up; Sami gives a thumbs-up."}],"captions_ar":["لدى سامي قصة لكم. استمعوا وانظروا.","مرحبًا! اسمي سامي. أنا ولد. عمري ثماني سنوات. شعري أسود قصير وعيناي بنيتان…","أسئلة \"الإجابة هنا\": الإجابة في القصة. كم عمر سامي؟ انظروا… ثماني سنوات!","أسئلة \"فكِّر\": هل سامي جديد في الفصل؟ ابحثوا عن دليل: \"يومي الأول في فصل جديد\". نعم، هو جديد!","أسئلة \"أنا\": هل تحب الكتب مثل سامي؟ قل: نعم، أحب الكتب. أو: لا، أحب كرة القدم.","الإجابة هنا، فكِّر، أنا! والآن اقرأ القصة أنت."],"voice":"Narrator: American English, warm female teacher, speed 0.8. Sami: bright 8-year-old boy voice, cheerful. Read the story slowly with a 1-second pause after each sentence."},"texts":[{"type":"reading","title":"Hello, I Am Sami","body":"Hello! My name is Sami. I am a boy. I am eight years old.\n\nI have short black hair and brown eyes. My hands are small, but my smile is big!\n\nI go to school in Taif. My friend is Omar. Omar is tall. He likes football.\n\nI like books and the moon. At school, I put up my hand and I ask, \"Why?\"\n\nToday is my first day in a new class. I say, \"Hello, I am Sami!\" I am happy. This is me!","word_count":85,"audio_id":"AUD-RW-L01-U1-LS2-T1","id":"TXT-RW-L01-U1-LS2-1","genre":"narrative","role":"main","difficulty":"BR–200L","glossary":[{"word":"Taif","definition":"a city in the mountains of Saudi Arabia","arabic":"الطائف"},{"word":"smile","definition":"a happy face with your mouth","arabic":"ابتسامة"},{"word":"put up my hand","definition":"raise my hand to speak","arabic":"أرفع يدي"}]}],"activities":[{"id":"RW-L01-U1-LS2-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Right There questions. Read the story and choose the answer.","instructions_ar":"أسئلة \"الإجابة هنا\": اقرأ القصة واختر الإجابة.","items":[{"q":"Who is the story about?","answer":"Sami","explanation":"The story says: My name is Sami.","explanation_ar":"القصة عن سامي.","options":["Omar","Sami","Noura","Saqr"],"dok":1,"skill":"key details: who","stage":"controlled"},{"q":"How old is Sami?","answer":"eight","explanation":"Text: I am eight years old.","explanation_ar":"عمره ثماني سنوات.","options":["eight","six","nine","ten"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What color is Sami's hair?","answer":"black","explanation":"Text: short black hair.","explanation_ar":"شعره أسود.","options":["brown","red","white","black"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Where is Sami's school?","answer":"in Taif","explanation":"Text: I go to school in Taif.","explanation_ar":"مدرسته في الطائف.","options":["in Jeddah","in a park","at home","in Taif"],"dok":1,"skill":"key details: where","stage":"controlled"},{"q":"What does Omar like?","answer":"football","explanation":"Text: He likes football.","explanation_ar":"عمر يحب كرة القدم.","options":["the moon","books","football","apples"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What are small in the story?","answer":"Sami's hands","explanation":"Text: My hands are small.","explanation_ar":"يدا سامي صغيرتان.","options":["Sami's hands","Sami's eyes","Omar's feet","the books"],"dok":1,"skill":"key details","stage":"controlled"}]},{"id":"RW-L01-U1-LS2-A2","type":"true_false","stage":"guided","instructions":"Guided practice: True or false? Circle one.","instructions_ar":"صح أم خطأ؟ ضع دائرة.","items":[{"q":"Sami is a girl.","answer":"false","explanation":"Sami says: I am a boy.","explanation_ar":"سامي ولد.","options":["true","false"],"stage":"guided"},{"q":"Sami has brown eyes.","answer":"true","explanation":"Text: brown eyes.","explanation_ar":"عينا سامي بنيتان.","options":["true","false"],"stage":"guided"},{"q":"Omar is short.","answer":"false","explanation":"Text: Omar is tall.","explanation_ar":"عمر طويل.","options":["true","false"],"stage":"guided"},{"q":"Sami likes books and the moon.","answer":"true","explanation":"Text: I like books and the moon.","explanation_ar":"سامي يحب الكتب والقمر.","options":["true","false"],"stage":"guided"},{"q":"Today is Sami's first day in a new class.","answer":"true","explanation":"Text: Today is my first day in a new class.","explanation_ar":"اليوم أول يوم لسامي في فصل جديد.","options":["true","false"],"stage":"guided"},{"q":"Sami is sad today.","answer":"false","explanation":"Text: I am happy.","explanation_ar":"سامي سعيد.","options":["true","false"],"stage":"guided"}]},{"id":"RW-L01-U1-LS2-A3","type":"highlight","stage":"freer","instructions":"Find the evidence: Think questions. Underline the evidence or choose the best answer.","instructions_ar":"أسئلة \"فكِّر\": ضع خطًا تحت الدليل أو اختر أفضل إجابة.","items":[{"q":"Underline the sentence that tells Sami's age.","answer":"I am eight years old.","explanation":"This sentence gives his age.","explanation_ar":"هذه الجملة تذكر عمره.","evidence":"I am eight years old.","text_id":"TXT-RW-L01-U1-LS2-1","dok":1,"skill":"evidence","stage":"freer","sentences":["Hello!","My name is Sami.","I am a boy.","I am eight years old.","I have short black hair and brown eyes.","My hands are small, but my smile is big!","I go to school in Taif.","My friend is Omar.","Omar is tall.","He likes football.","I like books and the moon.","At school, I put up my hand and I ask, \"Why?\"","Today is my first day in a new class.","I say, \"Hello, I am Sami!\"","I am happy.","This is me!"]},{"q":"Underline the words that show Sami asks questions at school.","answer":"At school, I put up my hand and I ask, \"Why?\"","explanation":"He puts up his hand and asks why.","explanation_ar":"يرفع يده ويسأل: لماذا؟","evidence":"At school, I put up my hand and I ask, \"Why?\"","text_id":"TXT-RW-L01-U1-LS2-1","dok":2,"skill":"evidence","stage":"freer","sentences":["Hello!","My name is Sami.","I am a boy.","I am eight years old.","I have short black hair and brown eyes.","My hands are small, but my smile is big!","I go to school in Taif.","My friend is Omar.","Omar is tall.","He likes football.","I like books and the moon.","At school, I put up my hand and I ask, \"Why?\"","Today is my first day in a new class.","I say, \"Hello, I am Sami!\"","I am happy.","This is me!"]},{"q":"Why does Sami put up his hand?","answer":"to ask a question","explanation":"He puts up his hand and asks, \"Why?\"","explanation_ar":"يرفع يده ليسأل سؤالًا.","options":["to play football","to say goodbye","to ask a question","to eat lunch"],"dok":2,"skill":"inference","stage":"freer"},{"q":"Sami says, \"Hello, I am Sami!\" Why?","answer":"The class is new, so he says his name.","explanation":"It is his first day in a new class.","explanation_ar":"الفصل جديد، فيعرّف بنفسه.","options":["He is very tired.","The class is new, so he says his name.","Omar is not his friend.","He is at home."],"dok":2,"skill":"inference","stage":"freer"}]},{"id":"RW-L01-U1-LS2-A4","type":"open","stage":"production","instructions":"Writing: Me questions. Write your answers.","instructions_ar":"أسئلة \"أنا\": اكتب إجاباتك.","items":[{"q":"Do you want Sami as a friend? Write *Yes* or *No* and one reason.","answer":"Yes. He likes books, and I like books too.","explanation":"Yes/No + a reason from the story.","explanation_ar":"نعم/لا مع سبب من القصة.","dok":3,"skill":"evaluate","stage":"production"},{"q":"Sami likes books and the moon. What do you like?","answer":"I like football and dates.","explanation":"A true sentence: I like ___.","explanation_ar":"جملة صحيحة: I like.","dok":2,"skill":"connect","stage":"production"},{"q":"Write one question you want to ask Sami.","answer":"Do you like football?","explanation":"Any question that ends with ?","explanation_ar":"أي سؤال ينتهي بعلامة استفهام.","dok":2,"skill":"question","stage":"production"},{"q":"Draw Sami. Write two labels from the story.","answer":"hair, hands","explanation":"Two correct labels.","explanation_ar":"بطاقتان صحيحتان.","dok":1,"skill":"labelling","stage":"production"}]},{"id":"RW-L01-U1-LS2-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"Hello, I Am Sami\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “Hello, I Am Sami”.","answer":"85 words","title":"Hello, I Am Sami","body":"Hello! My name is Sami. I am a boy. I am eight years old.\n\nI have short black hair and brown eyes. My hands are small, but my smile is big!\n\nI go to school in Taif. My friend is Omar. Omar is tall. He likes football.\n\nI like books and the moon. At school, I put up my hand and I ask, \"Why?\"\n\nToday is my first day in a new class. I say, \"Hello, I am Sami!\" I am happy. This is me!","words":85,"limit":142}],"time_limit_sec":142}],"game":{"name":"True or False Swipe","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Swipe game: a sentence card appears; swipe right for TRUE, left for FALSE. Correct = card flies to Sami's backpack with a chime; wrong = the evidence sentence flashes. 10 cards, 8 seconds each.","Every student holds a TRUE card and a FALSE card.","The teacher reads a sentence strip aloud and shows it.","Students count \"1, 2, 3\" and hold up one card.","The teacher shows the evidence sentence in the story.","Students with the right card stand up; after 10 sentences, students who stood up 8 times are Story Stars."],"data":[]},"exit_quiz":[{"q":"What is the boy's name in the story?","answer":"Sami","explanation":"He says: My name is Sami.","explanation_ar":"اسمه سامي.","options":["Sami","Omar","Adam","Ali"],"dok":1,"skill":"key details"},{"q":"Which sentence is in the story?","answer":"My friend is Omar.","explanation":"This sentence is in paragraph 3.","explanation_ar":"هذه الجملة في الفقرة الثالثة.","options":["My friend is Noura.","Omar is short.","I am nine.","My friend is Omar."],"dok":1,"skill":"key details"},{"q":"What color are Sami's eyes?","answer":"brown","explanation":"Text: brown eyes.","explanation_ar":"عيناه بنيتان.","options":["black","brown","blue","green"],"dok":1,"skill":"key details"},{"q":"Sami's smile is ___.","answer":"big","explanation":"Text: my smile is big.","explanation_ar":"ابتسامته كبيرة.","options":["small","short","new","big"],"dok":1,"skill":"key details"},{"q":"What two things does Sami like?","answer":"books and the moon","explanation":"Text: I like books and the moon.","explanation_ar":"يحب الكتب والقمر.","options":["football and cats","dates and milk","books and the moon","the sun and rain"],"dok":1,"skill":"key details"},{"q":"What does Sami ask at school?","answer":"\"Why?\"","explanation":"Text: I ask, \"Why?\"","explanation_ar":"يسأل: لماذا؟","options":["\"Where?\"","\"Why?\"","\"Who?\"","\"When?\""],"dok":1,"skill":"key details"},{"q":"Which word tells us the class is not old?","answer":"new","explanation":"A new class is not old.","explanation_ar":"كلمة new تعني جديد.","options":["first","happy","new","tall"],"dok":2,"skill":"word in context"},{"q":"What kind of question is *Where is Sami's school?*","answer":"Right There","explanation":"The answer is written in the story.","explanation_ar":"الإجابة مكتوبة في القصة.","options":["Think","Right There","Me","Picture"],"dok":2,"skill":"question types"},{"q":"Which clue shows that Sami feels good today?","answer":"I am happy.","explanation":"Happy means feeling good.","explanation_ar":"كلمة happy دليل على شعوره بالسعادة.","options":["I am happy.","Omar is tall.","I go to school in Taif.","My hands are small."],"dok":2,"skill":"evidence"},{"q":"Sami likes books and asks \"Why?\". What is true about Sami?","answer":"He likes to learn.","explanation":"Books and questions show he likes to learn.","explanation_ar":"حبه للكتب وأسئلته تدل على حبه للتعلم.","options":["He likes to learn.","He does not like school.","He is a teacher.","He is very old."],"dok":3,"skill":"inference"}],"images":[{"id":"IMG-RW-L01-U1-LS2-V01","prompt":"Picture for the word 'years old': a boy holding up eight fingers next to a birthday cake"},{"id":"IMG-RW-L01-U1-LS2-V02","prompt":"Picture for the word 'short': a short pencil next to a long pencil"},{"id":"IMG-RW-L01-U1-LS2-V03","prompt":"Picture for the word 'tall': a tall man standing next to a small boy"},{"id":"IMG-RW-L01-U1-LS2-V04","prompt":"Picture for the word 'smile': Grandpa Saleh smiling warmly"},{"id":"IMG-RW-L01-U1-LS2-V05","prompt":"Picture for the word 'ask': a boy with his hand up and a question-mark bubble"},{"id":"IMG-RW-L01-U1-LS2-V06","prompt":"Picture for the word 'first': a line of children, the front child marked by a gold star"},{"id":"IMG-RW-L01-U1-LS2-V07","prompt":"Picture for the word 'new': a shiny new school bag with a tag"},{"id":"IMG-RW-L01-U1-LS2-01","prompt":"Sami smiles with his hand up in a new classroom while Omar holds a football."},{"id":"IMG-RW-L01-U1-LS2-02","prompt":"Three icons: a finger on a page, a thinking cloud, and a child pointing to himself."},{"id":"IMG-RW-L01-U1-LS2-03","prompt":"Saqr the falcon in a detective hat looks through a magnifying glass."}],"audio":[{"id":"AUD-RW-L01-U1-LS2-V01","script":"years old. My sister is five years old."},{"id":"AUD-RW-L01-U1-LS2-V02","script":"short. The pencil is short."},{"id":"AUD-RW-L01-U1-LS2-V03","script":"tall. My father is tall."},{"id":"AUD-RW-L01-U1-LS2-V04","script":"smile. Grandpa has a kind smile."},{"id":"AUD-RW-L01-U1-LS2-V05","script":"ask. I ask my teacher a question."},{"id":"AUD-RW-L01-U1-LS2-V06","script":"first. Ali is first in the line."},{"id":"AUD-RW-L01-U1-LS2-V07","script":"new. I have a new bag."},{"id":"AUD-RW-L01-U1-LS2-T1","script":"Hello! My name is Sami. I am a boy. I am eight years old. I have short black hair and brown eyes. My hands are small, but my smile is big! I go to school in Taif. My friend is Omar. Omar is tall. He likes football. I like books and the moon. At school, I put up my hand and I ask, \"Why?\" Today is my first day in a new class. I say, \"Hello, I am Sami!\" I am happy. This is me!"},{"id":"AUD-RW-L01-U1-LS2-VID","script":"Sami has a story for you. Listen and look. Hello! My name is Sami. I am a boy. I am eight years old. I have short black hair and brown eyes… Right There questions! The answer is in the story. How old is Sami? Look… eight years old! Think questions! Is Sami new in the class? Find a clue… 'my first day in a new class'. Yes, he is new! Me questions! Do YOU like books like Sami? Say: Yes, I like books. Or: No, I like football. Right There, Think, Me! Now you read the story."}]},{"id":"RW-L01-U1-LS3","title":"Key details: who, what, where: \"I Am Me!\"","lesson_type":"strategy_paired_text","objectives":["ask and answer who, what and where questions about a story and a poem","find key details in a short poem and write them in a 5W Star organizer","hear and find rhyming words in a poem"],"objectives_ar":["طرح أسئلة من وماذا وأين والإجابة عنها حول قصة وقصيدة.","إيجاد التفاصيل المهمة في قصيدة قصيرة وكتابتها في منظِّم النجمة.","سماع الكلمات المتناغمة في القصيدة وإيجادها."],"success_criteria":["I can answer Who? What? Where?","I can find key details in a poem.","I can find two words that rhyme."],"success_criteria_ar":["أستطيع الإجابة عن: من؟ ماذا؟ أين؟","أستطيع إيجاد التفاصيل المهمة في القصيدة.","أستطيع إيجاد كلمتين متناغمتين."],"map_area":"Literary Text: Key Ideas and Details","vocabulary":[{"word":"poem","pos":"noun","ipa":"/ˈpoʊəm/","definition":"a short piece of writing in lines, often with rhyming words","arabic":"قصيدة","example":"Layla reads a poem about the sea.","image_id":"IMG-RW-L01-U1-LS3-V01","audio_id":"AUD-RW-L01-U1-LS3-V01","tier":"core"},{"word":"rhyme","pos":"verb","ipa":"/raɪm/","definition":"to end with the same sound","arabic":"يتناغم (في القافية)","example":"*Cat* and *hat* rhyme.","image_id":"IMG-RW-L01-U1-LS3-V02","audio_id":"AUD-RW-L01-U1-LS3-V02","tier":"core"},{"word":"long","pos":"adjective","ipa":"/lɔŋ/","definition":"not short","arabic":"طويل","example":"The train is long.","image_id":"IMG-RW-L01-U1-LS3-V03","audio_id":"AUD-RW-L01-U1-LS3-V03","tier":"core"},{"word":"same","pos":"adjective","ipa":"/seɪm/","definition":"not different","arabic":"نفسه / متشابه","example":"We have the same bag.","image_id":"IMG-RW-L01-U1-LS3-V04","audio_id":"AUD-RW-L01-U1-LS3-V04","tier":"core"},{"word":"see","pos":"verb","ipa":"/si/","definition":"to use your eyes to know what is there","arabic":"يرى","example":"I can see a bird.","image_id":"IMG-RW-L01-U1-LS3-V05","audio_id":"AUD-RW-L01-U1-LS3-V05","tier":"core"},{"word":"help","pos":"verb","ipa":"/hɛlp/","definition":"to do something good for someone","arabic":"يساعد","example":"I help my mother.","image_id":"IMG-RW-L01-U1-LS3-V06","audio_id":"AUD-RW-L01-U1-LS3-V06","tier":"core"},{"word":"family","pos":"noun","ipa":"/ˈfæməli/","definition":"your mother, father, brothers, sisters and you","arabic":"أسرة / عائلة","example":"My family eats dinner together.","image_id":"IMG-RW-L01-U1-LS3-V07","audio_id":"AUD-RW-L01-U1-LS3-V07","tier":"core"}],"explanation":{"text":"**Key details** are small, important facts in a text. Good readers ask questions to find them.\n\n**Who?** asks about a person or an animal. **What?** asks about a thing or an action. **Where?** asks about a place.\n\nUse the **5W Star**. Today we fill three points of the star: Who? What? Where?","examples":["Who is the poem about? → **Noura**.","Who is Sami's friend? → **Omar**.","What does Omar like? → **football**.","What does Noura have to read and see? → **two eyes**.","What is long? → **Noura's hair**.","Where does Sami go to school? → **in Taif**.","Where is Sami today? → **in a new class**.","Who are friends \"one and all\"? → **everyone – big or small, short or tall**.","What does Noura help with her hands? → **her family**."],"common_errors":["✗ Who is Noura? – Taif. → ✓ Who is Noura? – A girl. (**Who** asks about a person, not a place.)","✗ Where is Sami? – Omar. → ✓ Where is Sami? – In a new class. (**Where** asks about a place.)","✗ She is girl. → ✓ She is a girl. (Use **a** before one person or thing.)","✗ Where is Sami school? → ✓ Where is Sami's school? (Use **'s** to show it belongs to Sami.)","✗ What Noura likes? → ✓ What does Noura like? (We learn this question form later; for now, answer the question.)","✗ My hair is long. My age is nine. (read as one sentence) → ✓ Stop at the period: My hair is long. / My age is nine. (A period means stop and breathe.)"],"arabic":"التفاصيل المهمة هي حقائق صغيرة ومهمة في النص. القارئ الجيد يطرح أسئلة ليجدها.\n\nWho (مَن؟) للسؤال عن شخص أو حيوان. What (ماذا؟/ما؟) للسؤال عن شيء أو فعل. Where (أين؟) للسؤال عن مكان.\n\nنستخدم منظِّم النجمة، ونملأ اليوم ثلاث نقاط: مَن؟ ماذا؟ أين؟\n\nالقافية: كلمات تنتهي بالصوت نفسه مثل see و family، و name و same."},"video":{"script":[{"time":"00:00–00:15","narration":"Meet Noura! She has a poem for you.","on_screen":"I Am Me!","visual":"Noura sits at a desk drawing; the title appears on her drawing paper."},{"time":"00:15–00:55","narration":"I am a girl. Noura is my name. No one else is just the same…","on_screen":"(the poem, line by line)","visual":"Each line appears; rhyming words (name/same, see/family, nine/fine, small/tall/all) pulse in coral."},{"time":"00:55–01:20","narration":"Key details are small, important facts. Ask: Who? What? Where?","on_screen":"Who? What? Where?","visual":"A five-point star appears; three points light up with a person icon, a thing icon and a map pin."},{"time":"01:20–01:45","narration":"Who is the poem about? Noura! What is long? Her hair! Where is Sami's school? In Taif!","on_screen":"Who → Noura · What → hair · Where → Taif","visual":"Each answer flies into a star point."},{"time":"01:45–02:05","narration":"Rhyme time! Name, same. See, family. Can you hear it?","on_screen":"name – same · nine – fine","visual":"Saqr taps a drum on each rhyming pair."},{"time":"02:05–02:20","narration":"Now you be a detail detective!","on_screen":"Be a detail detective!","visual":"Noura and Sami hold up a star organizer and wave."}],"captions_ar":["تعرّفوا على نورة! لديها قصيدة لكم.","أنا بنت. اسمي نورة. لا أحد غيري مثلي تمامًا…","التفاصيل المهمة حقائق صغيرة مهمة. اسأل: مَن؟ ماذا؟ أين؟","عمّن القصيدة؟ عن نورة! ما الطويل؟ شعرها! أين مدرسة سامي؟ في الطائف!","وقت القافية! name و same. see و family. هل تسمعونها؟","والآن كن محققًا في التفاصيل!"],"voice":"Narrator: American English, warm female teacher, speed 0.8. Noura: gentle, confident 9-year-old girl voice reading with rhythm; slight pause at each rhyme."},"texts":[{"type":"reading","title":"I Am Me!","body":"I am a girl. Noura is my name.\n\nNo one else is just the same.\n\nI have two eyes to read and see,\n\ntwo hands to help my family.\n\nMy hair is long. My age is nine.\n\nI smile a lot, and that is fine!\n\nBig or small, short or tall,\n\nwe are friends, one and all.\n\nI am special, can't you see?\n\nI am happy. I am me!","word_count":69,"audio_id":"AUD-RW-L01-U1-LS3-T1","id":"TXT-RW-L01-U1-LS3-1","genre":"poetry (original)","role":"paired","difficulty":"BR–200L","glossary":[{"word":"one and all","definition":"everyone","arabic":"الجميع"},{"word":"can't you see?","definition":"do you not see it?","arabic":"ألا ترى؟"}]}],"activities":[{"id":"RW-L01-U1-LS3-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Is the word a Who, a What or a Where? Choose.","instructions_ar":"هل الكلمة مَن أم ماذا أم أين؟ اختر.","items":[{"q":"*Noura* answers which question?","answer":"Who?","explanation":"Noura is a person.","explanation_ar":"نورة شخص.","options":["What?","Where?","When?","Who?"],"dok":1,"skill":"question words","stage":"controlled"},{"q":"*Taif* answers which question?","answer":"Where?","explanation":"Taif is a place.","explanation_ar":"الطائف مكان.","options":["Who?","Where?","What?","When?"],"dok":1,"skill":"question words","stage":"controlled"},{"q":"*football* answers which question?","answer":"What?","explanation":"Football is a thing.","explanation_ar":"كرة القدم شيء.","options":["What?","Who?","Where?","When?"],"dok":1,"skill":"question words","stage":"controlled"},{"q":"*a new class* answers which question?","answer":"Where?","explanation":"A class is a place.","explanation_ar":"الفصل مكان.","options":["What?","Who?","Where?","When?"],"dok":1,"skill":"question words","stage":"controlled"},{"q":"*Omar* answers which question?","answer":"Who?","explanation":"Omar is a person.","explanation_ar":"عمر شخص.","options":["Where?","What?","Who?","When?"],"dok":1,"skill":"question words","stage":"controlled"},{"q":"*two hands* answers which question?","answer":"What?","explanation":"Hands are things (body parts).","explanation_ar":"اليدان شيء.","options":["Who?","Where?","When?","What?"],"dok":1,"skill":"question words","stage":"controlled"}]},{"id":"RW-L01-U1-LS3-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Read the poem \"I Am Me!\". Choose the key detail.","instructions_ar":"اقرأ قصيدة I Am Me! واختر التفصيل المهم.","items":[{"q":"Who wrote *I Am Me!* about herself?","answer":"Noura","explanation":"Line 1: Noura is my name.","explanation_ar":"السطر الأول: اسمي نورة.","options":["Sami","Omar","Layla","Noura"],"dok":1,"skill":"key details: who","text_id":"TXT-RW-L01-U1-LS3-1","stage":"guided"},{"q":"What is long?","answer":"Noura's hair","explanation":"Line 5: My hair is long.","explanation_ar":"شعرها طويل.","options":["Noura's hands","Noura's hair","the poem","the class"],"dok":1,"skill":"key details: what","stage":"guided"},{"q":"How old is Noura?","answer":"nine","explanation":"Line 5: My age is nine.","explanation_ar":"عمرها تسع سنوات.","options":["nine","eight","seven","ten"],"dok":1,"skill":"key details","stage":"guided"},{"q":"What does Noura use her two eyes for?","answer":"to read and see","explanation":"Line 3: two eyes to read and see.","explanation_ar":"تستخدم عينيها للقراءة والرؤية.","options":["to read and see","to help her family","to play football","to draw"],"dok":1,"skill":"key details: what","stage":"guided"},{"q":"Who does Noura help with her two hands?","answer":"her family","explanation":"Line 4: two hands to help my family.","explanation_ar":"تساعد أسرتها.","options":["her teacher","Omar","a cat","her family"],"dok":1,"skill":"key details: who","stage":"guided"},{"q":"Which word rhymes with *see*?","answer":"family","explanation":"See and family end with the same sound.","explanation_ar":"see و family لهما الصوت نفسه في النهاية.","options":["small","nine","family","name"],"dok":2,"skill":"rhyme","stage":"guided"}]},{"id":"RW-L01-U1-LS3-A3","type":"open","stage":"freer","instructions":"Freer practice: Answer with a key detail. Use the story and the poem.","instructions_ar":"أجب بتفصيل مهم من القصة والقصيدة.","items":[{"q":"Who is in the story *Hello, I Am Sami*? Write two names.","answer":"Sami and Omar","explanation":"Both boys are in the story.","explanation_ar":"سامي وعمر.","dok":1,"skill":"key details: who","stage":"freer"},{"q":"Where does Sami go to school?","answer":"He goes to school in Taif.","explanation":"Text: in Taif.","explanation_ar":"في الطائف.","dok":1,"skill":"key details: where","stage":"freer"},{"q":"What does Noura do a lot? (line 6)","answer":"She smiles a lot.","explanation":"Line 6: I smile a lot.","explanation_ar":"تبتسم كثيرًا.","dok":1,"skill":"key details: what","stage":"freer"},{"q":"Who are friends in the poem? Write the words from line 7.","answer":"Big or small, short or tall – everyone.","explanation":"Everyone is a friend.","explanation_ar":"الجميع أصدقاء.","dok":2,"skill":"key details: who","stage":"freer"}]},{"id":"RW-L01-U1-LS3-A4","type":"open","stage":"production","instructions":"Writing: Make a 5W Star about YOU. Write a sentence for each point.","instructions_ar":"اصنع نجمة عن نفسك واكتب جملة لكل نقطة.","items":[{"q":"Who are you?","answer":"I am Huda. I am a girl.","explanation":"Name + boy/girl.","explanation_ar":"الاسم + ولد/بنت.","dok":1,"skill":"writing key details","stage":"production"},{"q":"What do you like?","answer":"I like books.","explanation":"I like + a thing.","explanation_ar":"I like + شيء.","dok":1,"skill":"writing key details","stage":"production"},{"q":"Where is your school?","answer":"My school is in Taif.","explanation":"My school is in + place.","explanation_ar":"My school is in + مكان.","dok":1,"skill":"writing key details","stage":"production"},{"q":"Write two words that rhyme. Use one from the poem.","answer":"tall – ball","explanation":"Any two words that end with the same sound.","explanation_ar":"أي كلمتين تنتهيان بالصوت نفسه.","dok":2,"skill":"rhyme","stage":"production"}]},{"id":"RW-L01-U1-LS3-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"I Am Me!\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “I Am Me!”.","answer":"69 words","title":"I Am Me!","body":"I am a girl. Noura is my name.\n\nNo one else is just the same.\n\nI have two eyes to read and see,\n\ntwo hands to help my family.\n\nMy hair is long. My age is nine.\n\nI smile a lot, and that is fine!\n\nBig or small, short or tall,\n\nwe are friends, one and all.\n\nI am special, can't you see?\n\nI am happy. I am me!","words":69,"limit":118}],"time_limit_sec":118},{"id":"RW-L01-U1-LS3-ORG","type":"organizer","organizer":"5W Star (Who? What? Where?)","instructions":"Organizer: Write one key detail in each point of the star. Use the poem \"I Am Me!\".","items":[{"q":"Who? (a person)","answer":"Noura"},{"q":"What? (a thing)","answer":"two eyes and two hands; long hair"},{"q":"Where? (a place)","answer":"with her family; with her friends"}]}],"game":{"name":"Who-What-Where Sort","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Drag-and-drop sorting: cards drop one at a time; the child drags each into the Who, What or Where basket. Correct = basket glows and says the question; wrong = card bounces back with a hint icon. 45 seconds per round, 3 rounds.","Make three teams. Each team gets 6 cards face down.","When the teacher says \"Go!\", a student turns over a card, reads it and puts it in the right hoop.","The next student does the next card (relay).","When all cards are sorted, the teacher checks each hoop with the class.","One point for each correct card; the fastest team with all cards correct gets 3 bonus points."],"data":[]},"exit_quiz":[{"q":"Which question word asks about a place?","answer":"Where?","explanation":"Where asks about a place.","explanation_ar":"Where للسؤال عن المكان.","options":["Who?","What?","Where?","Why?"],"dok":1,"skill":"question words"},{"q":"Which question word asks about a person?","answer":"Who?","explanation":"Who asks about a person.","explanation_ar":"Who للسؤال عن الشخص.","options":["Where?","What?","How?","Who?"],"dok":1,"skill":"question words"},{"q":"In the poem, what is nine?","answer":"Noura's age","explanation":"Line 5: My age is nine.","explanation_ar":"عمر نورة تسع سنوات.","options":["Noura's hair","Sami's class","Noura's age","Omar's friends"],"dok":1,"skill":"key details"},{"q":"Noura has two ___ to help her family.","answer":"hands","explanation":"Line 4: two hands to help my family.","explanation_ar":"يدان لمساعدة أسرتها.","options":["eyes","hands","books","friends"],"dok":1,"skill":"key details"},{"q":"Which pair of words rhymes?","answer":"nine – fine","explanation":"Nine and fine end with the same sound.","explanation_ar":"nine و fine متناغمتان.","options":["girl – name","eyes – long","nine – fine","help – tall"],"dok":1,"skill":"rhyme"},{"q":"A key detail is ___.","answer":"a small, important fact","explanation":"Key details are small, important facts.","explanation_ar":"التفصيل المهم حقيقة صغيرة مهمة.","options":["a small, important fact","a picture of a key","the last word in a text","a long story"],"dok":1,"skill":"strategy"},{"q":"*Big or small, short or tall, we are friends, one and all.* Who are friends?","answer":"everyone","explanation":"One and all means everyone.","explanation_ar":"one and all تعني الجميع.","options":["only big children","only Noura","only tall children","everyone"],"dok":2,"skill":"key details in context"},{"q":"Which detail is in BOTH the story and the poem?","answer":"a child talks about hair and age","explanation":"Sami and Noura both talk about their hair and age.","explanation_ar":"سامي ونورة يتحدثان عن الشعر والعمر.","options":["a child talks about hair and age","a child plays football","a child lives in Jeddah","a child is sad"],"dok":2,"skill":"connect texts"},{"q":"Noura says, *No one else is just the same.* What does she mean?","answer":"Every person is different.","explanation":"No one is the same as her, so every person is different.","explanation_ar":"كل شخص مختلف عن غيره.","options":["Everyone looks the same.","Every person is different.","She has no friends.","Her name is long."],"dok":3,"skill":"inference"},{"q":"Which is the best Who? answer for *Hello, I Am Sami*?","answer":"Sami and his friend Omar","explanation":"Sami and Omar are the people in the story.","explanation_ar":"سامي وعمر هما الشخصان في القصة.","options":["books and the moon","Sami and his friend Omar","in Taif","the first day"],"dok":2,"skill":"key details: who"}],"images":[{"id":"IMG-RW-L01-U1-LS3-V01","prompt":"Picture for the word 'poem': a page with short lines and a small drawing of a bird"},{"id":"IMG-RW-L01-U1-LS3-V02","prompt":"Picture for the word 'rhyme': a cat wearing a hat"},{"id":"IMG-RW-L01-U1-LS3-V03","prompt":"Picture for the word 'long': a long green train"},{"id":"IMG-RW-L01-U1-LS3-V04","prompt":"Picture for the word 'same': two identical blue school bags side by side"},{"id":"IMG-RW-L01-U1-LS3-V05","prompt":"Picture for the word 'see': a child looking up at a bird in a palm tree"},{"id":"IMG-RW-L01-U1-LS3-V06","prompt":"Picture for the word 'help': a girl carrying a basket of fruit for her mother"},{"id":"IMG-RW-L01-U1-LS3-V07","prompt":"Picture for the word 'family': a Saudi family sitting together on a floor mat at dinner"},{"id":"IMG-RW-L01-U1-LS3-01","prompt":"Noura draws a picture of herself while her family watches."},{"id":"IMG-RW-L01-U1-LS3-02","prompt":"A star organizer with icons for who, what and where."},{"id":"IMG-RW-L01-U1-LS3-03","prompt":"Children sort cards into three hoops."}],"audio":[{"id":"AUD-RW-L01-U1-LS3-V01","script":"poem. Layla reads a poem about the sea."},{"id":"AUD-RW-L01-U1-LS3-V02","script":"rhyme. *Cat* and *hat* rhyme."},{"id":"AUD-RW-L01-U1-LS3-V03","script":"long. The train is long."},{"id":"AUD-RW-L01-U1-LS3-V04","script":"same. We have the same bag."},{"id":"AUD-RW-L01-U1-LS3-V05","script":"see. I can see a bird."},{"id":"AUD-RW-L01-U1-LS3-V06","script":"help. I help my mother."},{"id":"AUD-RW-L01-U1-LS3-V07","script":"family. My family eats dinner together."},{"id":"AUD-RW-L01-U1-LS3-T1","script":"I am a girl. Noura is my name. No one else is just the same. I have two eyes to read and see, two hands to help my family. My hair is long. My age is nine. I smile a lot, and that is fine! Big or small, short or tall, we are friends, one and all. I am special, can't you see? I am happy. I am me!"},{"id":"AUD-RW-L01-U1-LS3-VID","script":"Meet Noura! She has a poem for you. I am a girl. Noura is my name. No one else is just the same… Key details are small, important facts. Ask: Who? What? Where? Who is the poem about? Noura! What is long? Her hair! Where is Sami's school? In Taif! Rhyme time! Name, same. See, family. Can you hear it? Now you be a detail detective!"}]},{"id":"RW-L01-U1-LS4","title":"Writing Skill: Capital letters and periods","lesson_type":"writing_skill","objectives":["begin every sentence with a capital letter and end it with a period","use capital letters for the word I and for names of people and places","find and fix capital-letter and period mistakes in short sentences"],"objectives_ar":["بدء كل جملة بحرف كبير وإنهاؤها بنقطة.","استخدام الحرف الكبير لكلمة I ولأسماء الأشخاص والأماكن.","إيجاد أخطاء الحروف الكبيرة والنقطة وتصحيحها في جمل قصيرة."],"success_criteria":["I can start a sentence with a capital letter.","I can end a sentence with a period.","I can write I, names and places with a capital letter."],"success_criteria_ar":["أستطيع بدء الجملة بحرف كبير.","أستطيع إنهاء الجملة بنقطة.","أستطيع كتابة I والأسماء والأماكن بحرف كبير."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"sentence","pos":"noun","ipa":"/ˈsɛntəns/","definition":"a group of words that tells a full idea","arabic":"جملة","example":"This sentence has four words.","image_id":"IMG-RW-L01-U1-LS4-V01","audio_id":"AUD-RW-L01-U1-LS4-V01","tier":"core"},{"word":"word","pos":"noun","ipa":"/wɝd/","definition":"a group of letters with a meaning","arabic":"كلمة","example":"Cat is a short word.","image_id":"IMG-RW-L01-U1-LS4-V02","audio_id":"AUD-RW-L01-U1-LS4-V02","tier":"core"},{"word":"capital letter","pos":"noun","ipa":"/ˈkæpətəl ˈlɛtər/","definition":"a big letter, like A, B, C","arabic":"حرف كبير","example":"S is a capital letter.","image_id":"IMG-RW-L01-U1-LS4-V03","audio_id":"AUD-RW-L01-U1-LS4-V03","tier":"core"},{"word":"period","pos":"noun","ipa":"/ˈpɪriəd/","definition":"the dot (.) at the end of a sentence","arabic":"نقطة","example":"Put a period at the end.","image_id":"IMG-RW-L01-U1-LS4-V04","audio_id":"AUD-RW-L01-U1-LS4-V04","tier":"core"},{"word":"space","pos":"noun","ipa":"/speɪs/","definition":"an empty place between two words","arabic":"مسافة","example":"Leave a space between words.","image_id":"IMG-RW-L01-U1-LS4-V05","audio_id":"AUD-RW-L01-U1-LS4-V05","tier":"core"},{"word":"begin","pos":"verb","ipa":"/bɪˈɡɪn/","definition":"to start","arabic":"يبدأ","example":"Sentences begin with a capital letter.","image_id":"IMG-RW-L01-U1-LS4-V06","audio_id":"AUD-RW-L01-U1-LS4-V06","tier":"core"},{"word":"end","pos":"verb","ipa":"/ɛnd/","definition":"to stop; to finish","arabic":"ينتهي","example":"The story ends happily.","image_id":"IMG-RW-L01-U1-LS4-V07","audio_id":"AUD-RW-L01-U1-LS4-V07","tier":"core"}],"explanation":{"text":"A **sentence** is a group of words with a full idea.\n\nEvery sentence **begins** with a **capital letter** and **ends** with a **period** (.). Think: green to go, red to stop.\n\nUse a capital letter for: the **first word** of a sentence, the word **I**, **names of people** (Sami, Noura) and **names of places** (Taif, Makkah).\n\nPut a **space** (one finger) between words.","examples":["**M**y name is **S**ami**.**","**I** am happy**.**","**O**mar is my friend**.**","**W**e go to school in **T**aif**.**","**N**oura likes to draw**.**","**M**y friend **L**ayla and **I** read books**.**","**T**he cat is small**.**","**G**randpa **S**aleh lives in **M**akkah**.**","my name is ali → **M**y name is **A**li**.**"],"common_errors":["✗ my name is sami → ✓ My name is Sami. (Arabic has no capital letters, so we forget them in English.)","✗ i am happy. → ✓ I am happy. (The word **I** is always a capital.)","✗ I Like Books. → ✓ I like books. (Do not put capitals in the middle without a reason.)","✗ I am eight → ✓ I am eight. (Do not forget the period at the end.)","✗ .I am a boy → ✓ I am a boy. (English goes left to right; the period goes at the **end** on the right.)","✗ Mynameis Omar. → ✓ My name is Omar. (Leave a finger space between words.)","✗ I live in taif. → ✓ I live in Taif. (Names of places begin with a capital.)"],"arabic":"الجملة مجموعة كلمات تعطي فكرة كاملة.\n\nكل جملة تبدأ بحرف كبير (capital letter) وتنتهي بنقطة (period). فكّر: الأخضر للبدء والأحمر للتوقف.\n\nنستخدم الحرف الكبير في: أول كلمة في الجملة، وكلمة I دائمًا، وأسماء الأشخاص مثل Sami، وأسماء الأماكن مثل Taif.\n\nاترك مسافة بقدر إصبع بين كل كلمتين. وتذكّر أن الإنجليزية تُكتب من اليسار إلى اليمين، فالنقطة توضع في آخر الجملة جهة اليمين."},"video":{"script":[{"time":"00:00–00:15","narration":"Every sentence needs two helpers: a capital letter and a period!","on_screen":"Capital letter + period","visual":"Saqr holds a big green capital A in one claw and a red dot in the other."},{"time":"00:15–00:45","narration":"Look: my name is sami. Something is wrong! Begin with a capital M. Sami is a name – capital S. End with a period.","on_screen":"my name is sami → My name is Sami.","visual":"The lowercase m and s jump up and grow into capitals; a red period rolls in and clicks into place."},{"time":"00:45–01:10","narration":"The word I is always big. I am happy. I like books.","on_screen":"I am happy.","visual":"A tall letter I stands like a soldier; small i tries to sit but stands up straight again."},{"time":"01:10–01:40","narration":"Names of people and places begin with a capital: Noura, Omar, Taif, Makkah.","on_screen":"Noura · Omar · Taif · Makkah","visual":"Name tags float over the cast; a map pin drops on Taif and Makkah."},{"time":"01:40–02:05","narration":"Green to go, red to stop! Begin with a capital. Stop with a period.","on_screen":"🟢 capital … period 🔴","visual":"A sentence strip becomes a little road with a green light at the start and a red light at the end."},{"time":"02:05–02:30","narration":"Now you are the sentence fixer!","on_screen":"Sentence fixer!","visual":"Noura holds up her notebook page 'All About Me'; capitals and periods sparkle."}],"captions_ar":["كل جملة تحتاج إلى مساعدين: حرف كبير ونقطة!","انظر: my name is sami. هناك خطأ! ابدأ بحرف M كبير. Sami اسم فيبدأ بحرف S كبير. وانتهِ بنقطة.","كلمة I تُكتب دائمًا بحرف كبير.","أسماء الأشخاص والأماكن تبدأ بحرف كبير: نورة، عمر، الطائف، مكة.","الأخضر للبدء والأحمر للتوقف! ابدأ بحرف كبير وتوقف بنقطة.","والآن أنت مصلِّح الجمل!"],"voice":"Narrator: American English, warm female teacher, speed 0.8, upbeat. Saqr: playful young male voice. Short pauses so children can say \"capital!\" and \"period!\" with the video."},"texts":[{"type":"model","title":"All About Me (from Noura's Notebook)","body":"My name is Noura. I am a girl. I am nine years old. I have long black hair. I like to draw.\n\nMy friend is Layla. We go to school in Taif. I am happy!","word_count":35,"audio_id":"AUD-RW-L01-U1-LS4-T1","id":"TXT-RW-L01-U1-LS4-1","genre":"model text","role":"model","difficulty":"BR–200L","glossary":[],"annotations":["**M**y – a capital letter begins every sentence.","**N**oura, **L**ayla – names of people begin with a capital letter.","**T**aif – names of places begin with a capital letter.","**I** – the word I is always a capital letter.","old**.** – a period ends every sentence.","happy**!** – an exclamation mark ends a sentence with a strong feeling.","One finger space goes between two words."]}],"activities":[{"id":"RW-L01-U1-LS4-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the correct sentence.","instructions_ar":"اختر الجملة الصحيحة.","items":[{"q":"Which sentence about Huda is written correctly?","answer":"My name is Huda.","explanation":"Capital M, capital H for the name, and a period.","explanation_ar":"حرف كبير في البداية وفي الاسم، ونقطة في النهاية.","options":["my name is Huda.","My name is huda.","My name is Huda.","My name is Huda"],"dok":1,"skill":"capitals and periods","stage":"controlled"},{"q":"Which sentence about dates is written correctly?","answer":"I like dates.","explanation":"Capital I, a period, and no capitals in the middle.","explanation_ar":"I كبيرة ونقطة في النهاية.","options":["i like dates.","I like dates.","I like dates","I Like Dates."],"dok":1,"skill":"capitals and periods","stage":"controlled"},{"q":"Which sentence about Riyadh is written correctly?","answer":"We live in Riyadh.","explanation":"Riyadh is a place, so it begins with a capital.","explanation_ar":"الرياض اسم مكان.","options":["We live in Riyadh.","we live in Riyadh.","We live in riyadh.","We live in Riyadh"],"dok":1,"skill":"capitals for places","stage":"controlled"},{"q":"Which sentence about Ali is written correctly?","answer":"Ali and I play.","explanation":"Capital A for the name, capital I, period.","explanation_ar":"اسم علي وكلمة I بحرف كبير.","options":["Ali and i play.","Ali and I play.","ali and I play.","Ali and I play"],"dok":1,"skill":"capital I","stage":"controlled"},{"q":"Which sentence about the bag is written correctly?","answer":"The bag is red.","explanation":"Capital only at the start; period at the end.","explanation_ar":"حرف كبير في البداية فقط.","options":["The bag is red.","the bag is red.","The bag is red","The Bag is red."],"dok":1,"skill":"capitals and periods","stage":"controlled"},{"q":"Which sentence about Fahad is written correctly?","answer":"My friend Fahad is tall.","explanation":"Capital M, capital F for the name, period.","explanation_ar":"حرف كبير لاسم فهد.","options":["My friend fahad is tall.","my friend Fahad is tall.","My friend Fahad is tall","My friend Fahad is tall."],"dok":2,"skill":"capitals for names","stage":"controlled"}]},{"id":"RW-L01-U1-LS4-A2","type":"open","stage":"guided","instructions":"Guided practice: Write each sentence correctly. Add capital letters and a period.","instructions_ar":"اكتب كل جملة بشكل صحيح بإضافة الحروف الكبيرة والنقطة.","items":[{"q":"i am a girl","answer":"I am a girl.","explanation":"Capital I and a period.","explanation_ar":"I كبيرة ونقطة.","dok":1,"skill":"editing","stage":"guided"},{"q":"my sister is five","answer":"My sister is five.","explanation":"Capital M and a period.","explanation_ar":"M كبيرة ونقطة.","dok":1,"skill":"editing","stage":"guided"},{"q":"omar likes football","answer":"Omar likes football.","explanation":"Omar is a name.","explanation_ar":"Omar اسم شخص.","dok":1,"skill":"editing","stage":"guided"},{"q":"we go to school in jeddah","answer":"We go to school in Jeddah.","explanation":"Jeddah is a place.","explanation_ar":"جدة اسم مكان.","dok":2,"skill":"editing","stage":"guided"},{"q":"sami and i read books","answer":"Sami and I read books.","explanation":"Capital S (name, first word) and capital I.","explanation_ar":"S كبيرة وI كبيرة.","dok":2,"skill":"editing","stage":"guided"},{"q":"my teacher is mr. khalid","answer":"My teacher is Mr. Khalid.","explanation":"Mr. and Khalid begin with capitals.","explanation_ar":"Mr. وKhalid بحرف كبير.","dok":2,"skill":"editing","stage":"guided"}]},{"id":"RW-L01-U1-LS4-A3","type":"open","stage":"freer","instructions":"Freer practice: Be a sentence fixer! Read Adam's note. Find the mistake in each sentence and write it correctly.","instructions_ar":"كن مصلِّح الجمل! اقرأ ملاحظة آدم، وأصلح الخطأ في كل جملة.","items":[{"q":"hello, I am Adam.","answer":"Hello, I am Adam.","explanation":"The first word needs a capital.","explanation_ar":"أول كلمة تحتاج حرفًا كبيرًا.","dok":2,"skill":"editing","stage":"freer"},{"q":"I am nine years old","answer":"I am nine years old.","explanation":"Add a period at the end.","explanation_ar":"أضف نقطة في النهاية.","dok":2,"skill":"editing","stage":"freer"},{"q":"My friend is sami.","answer":"My friend is Sami.","explanation":"Sami is a name.","explanation_ar":"سامي اسم شخص.","dok":2,"skill":"editing","stage":"freer"},{"q":"i like computers.","answer":"I like computers.","explanation":"The word I is always a capital.","explanation_ar":"كلمة I دائمًا كبيرة.","dok":2,"skill":"editing","stage":"freer"}]},{"id":"RW-L01-U1-LS4-A4","type":"open","stage":"production","instructions":"Writing: Write 4 sentences about you. Begin with a capital letter. End with a period.","instructions_ar":"اكتب 4 جمل عن نفسك. ابدأ بحرف كبير وانتهِ بنقطة.","items":[{"q":"Sentence 1: your name.","answer":"My name is Fahad.","explanation":"Capital + name + period.","explanation_ar":"حرف كبير واسم ونقطة.","dok":1,"skill":"sentence writing","stage":"production"},{"q":"Sentence 2: your age.","answer":"I am nine years old.","explanation":"I am ___ years old.","explanation_ar":"I am ___ years old.","dok":1,"skill":"sentence writing","stage":"production"},{"q":"Sentence 3: a friend.","answer":"My friend is Majed.","explanation":"Capital letter for the friend's name.","explanation_ar":"اسم الصديق بحرف كبير.","dok":2,"skill":"sentence writing","stage":"production"},{"q":"Sentence 4: a place.","answer":"I live in Taif.","explanation":"Capital letter for the place.","explanation_ar":"اسم المكان بحرف كبير.","dok":2,"skill":"sentence writing","stage":"production"}]}],"game":{"name":"Capital Catch","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Tap-to-fix: a sentence appears with one mistake; the child taps the letter that should be a capital or drags a red period to the end. Correct = the letter grows into a capital with a pop sound. 10 sentences, 10 seconds each; a streak bonus for 3 in a row.","Make four teams. Each team has a bell or a buzzer card.","The teacher shows a sentence card.","If the sentence is correct, the first team to ring says \"Correct!\" If there is a mistake, they must say what to fix (\"Capital S for Sami!\").","Right answer = 1 point; wrong answer = the next team may answer.","After 10 cards, the team with the most points is the Capital Champion."],"data":[]},"exit_quiz":[{"q":"A sentence begins with ___.","answer":"a capital letter","explanation":"Every sentence begins with a capital letter.","explanation_ar":"كل جملة تبدأ بحرف كبير.","options":["a period","a space","a capital letter","a number"],"dok":1,"skill":"rule"},{"q":"A sentence ends with ___.","answer":"a period","explanation":"Every sentence ends with a period.","explanation_ar":"كل جملة تنتهي بنقطة.","options":["a period","a capital letter","a name","a space"],"dok":1,"skill":"rule"},{"q":"Which word must always be a capital letter?","answer":"I","explanation":"The word I is always a capital.","explanation_ar":"كلمة I دائمًا بحرف كبير.","options":["a","the","is","I"],"dok":1,"skill":"rule"},{"q":"Which word needs a capital letter?","answer":"makkah","explanation":"Makkah is the name of a place.","explanation_ar":"مكة اسم مكان.","options":["school","girl","makkah","happy"],"dok":1,"skill":"capitals for places"},{"q":"Which sentence about Majed is correct?","answer":"Majed is my brother.","explanation":"Capital M and a period only.","explanation_ar":"حرف كبير في البداية ونقطة في النهاية.","options":["majed is my brother.","Majed is my brother.","Majed is my brother","Majed Is my brother."],"dok":1,"skill":"capitals and periods"},{"q":"Where does the period go?","answer":"at the end of the sentence","explanation":"The period goes at the end.","explanation_ar":"النقطة في نهاية الجملة.","options":["at the start of the sentence","after every word","in the middle of a name","at the end of the sentence"],"dok":1,"skill":"rule"},{"q":"What is missing? *The book is new*","answer":"a period","explanation":"The sentence needs a period at the end.","explanation_ar":"ينقصها نقطة في النهاية.","options":["a period","a capital letter","a space","a name"],"dok":2,"skill":"editing"},{"q":"What is wrong? *my bag is blue.*","answer":"My needs a capital M.","explanation":"The first word needs a capital letter.","explanation_ar":"أول كلمة تحتاج حرفًا كبيرًا.","options":["Blue needs a capital B.","It needs two periods.","Nothing is wrong.","My needs a capital M."],"dok":2,"skill":"editing"},{"q":"Which sentence uses capital letters correctly?","answer":"Layla and I live in Taif.","explanation":"Capitals for Layla, I and Taif only.","explanation_ar":"حروف كبيرة لـ Layla وI وTaif فقط.","options":["Layla and i live in Taif.","layla and I live in taif.","Layla and I live in Taif.","Layla And I Live In Taif."],"dok":2,"skill":"capitals for names"},{"q":"How many sentences are here? *I am Sami. I am eight. I like the moon.*","answer":"three","explanation":"There are three periods, so there are three sentences.","explanation_ar":"توجد ثلاث نقاط، إذًا ثلاث جمل.","options":["one","three","two","four"],"dok":3,"skill":"sentence boundaries"}],"images":[{"id":"IMG-RW-L01-U1-LS4-V01","prompt":"Picture for the word 'sentence': a sentence strip with a green dot at the start and a red dot at the end"},{"id":"IMG-RW-L01-U1-LS4-V02","prompt":"Picture for the word 'word': letter tiles forming a short word on a table"},{"id":"IMG-RW-L01-U1-LS4-V03","prompt":"Picture for the word 'capital letter': a large letter S next to a small letter s"},{"id":"IMG-RW-L01-U1-LS4-V04","prompt":"Picture for the word 'period': a big red dot at the end of a sentence strip"},{"id":"IMG-RW-L01-U1-LS4-V05","prompt":"Picture for the word 'space': a child's finger placed between two written words"},{"id":"IMG-RW-L01-U1-LS4-V06","prompt":"Picture for the word 'begin': a green traffic light next to the start of a line of words"},{"id":"IMG-RW-L01-U1-LS4-V07","prompt":"Picture for the word 'end': a red stop sign at the end of a road"},{"id":"IMG-RW-L01-U1-LS4-01","prompt":"Noura's open notebook with a purple pen."},{"id":"IMG-RW-L01-U1-LS4-02","prompt":"A road with a green light at the start and a red light at the end."},{"id":"IMG-RW-L01-U1-LS4-03","prompt":"Saqr holds a big letter A and a red dot."}],"audio":[{"id":"AUD-RW-L01-U1-LS4-V01","script":"sentence. This sentence has four words."},{"id":"AUD-RW-L01-U1-LS4-V02","script":"word. Cat is a short word."},{"id":"AUD-RW-L01-U1-LS4-V03","script":"capital letter. S is a capital letter."},{"id":"AUD-RW-L01-U1-LS4-V04","script":"period. Put a period at the end."},{"id":"AUD-RW-L01-U1-LS4-V05","script":"space. Leave a space between words."},{"id":"AUD-RW-L01-U1-LS4-V06","script":"begin. Sentences begin with a capital letter."},{"id":"AUD-RW-L01-U1-LS4-V07","script":"end. The story ends happily."},{"id":"AUD-RW-L01-U1-LS4-T1","script":"My name is Noura. I am a girl. I am nine years old. I have long black hair. I like to draw. My friend is Layla. We go to school in Taif. I am happy!"},{"id":"AUD-RW-L01-U1-LS4-VID","script":"Every sentence needs two helpers: a capital letter and a period! Look: my name is sami. Something is wrong! Begin with a capital M. Sami is a name – capital S. End with a period. The word I is always big. I am happy. I like books. Names of people and places begin with a capital: Noura, Omar, Taif, Makkah. Green to go, red to stop! Begin with a capital. Stop with a period. Now you are the sentence fixer!"}]},{"id":"RW-L01-U1-LS5","title":"Writing Workshop: All About Me","lesson_type":"writing_workshop","objectives":["plan, draft, revise, edit and publish 3–4 sentences about themselves with a labelled drawing","use sentence frames and core unit words correctly (name, age, hair, eyes, like)","check their own writing for capital letters and periods with a checklist"],"objectives_ar":["التخطيط والكتابة والمراجعة والتدقيق والنشر لـ 3–4 جمل عن أنفسهم مع رسم عليه بطاقات.","استخدام أُطر الجمل وكلمات الوحدة الأساسية بشكل صحيح.","مراجعة كتابتهم من حيث الحروف الكبيرة والنقاط باستخدام قائمة تحقق."],"success_criteria":["I can plan my writing with a drawing and labels.","I can write 3–4 sentences about me.","I can check my capitals and periods and share my writing."],"success_criteria_ar":["أستطيع التخطيط لكتابتي برسم وبطاقات.","أستطيع كتابة 3–4 جمل عن نفسي.","أستطيع مراجعة الحروف الكبيرة والنقاط ومشاركة كتابتي."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"plan","pos":"verb","ipa":"/plæn/","definition":"to think about what you will do before you do it","arabic":"يخطط","example":"We plan our writing first.","image_id":"IMG-RW-L01-U1-LS5-V01","audio_id":"AUD-RW-L01-U1-LS5-V01","tier":"core"},{"word":"draw","pos":"verb","ipa":"/drɔ/","definition":"to make a picture with a pencil","arabic":"يرسم","example":"Layla can draw a cat.","image_id":"IMG-RW-L01-U1-LS5-V02","audio_id":"AUD-RW-L01-U1-LS5-V02","tier":"core"},{"word":"write","pos":"verb","ipa":"/raɪt/","definition":"to make words on paper","arabic":"يكتب","example":"Please write your name here.","image_id":"IMG-RW-L01-U1-LS5-V03","audio_id":"AUD-RW-L01-U1-LS5-V03","tier":"core"},{"word":"check","pos":"verb","ipa":"/tʃɛk/","definition":"to look again to find mistakes","arabic":"يراجع / يتحقق","example":"Check your spelling.","image_id":"IMG-RW-L01-U1-LS5-V04","audio_id":"AUD-RW-L01-U1-LS5-V04","tier":"core"},{"word":"share","pos":"verb","ipa":"/ʃɛr/","definition":"to show or give something to others","arabic":"يشارك","example":"We share our stories with the class.","image_id":"IMG-RW-L01-U1-LS5-V05","audio_id":"AUD-RW-L01-U1-LS5-V05","tier":"core"},{"word":"title","pos":"noun","ipa":"/ˈtaɪtəl/","definition":"the name of a story or a piece of writing","arabic":"عنوان","example":"The title of my story is \"Me\".","image_id":"IMG-RW-L01-U1-LS5-V06","audio_id":"AUD-RW-L01-U1-LS5-V06","tier":"core"},{"word":"picture","pos":"noun","ipa":"/ˈpɪktʃər/","definition":"a drawing or a photo","arabic":"صورة","example":"This picture shows my family.","image_id":"IMG-RW-L01-U1-LS5-V07","audio_id":"AUD-RW-L01-U1-LS5-V07","tier":"core"}],"explanation":{"text":"Good writers use five steps. We call them the **writing process**.\n\n**1. Plan** – think and draw. **2. Draft** – write your sentences. **3. Revise** – make it better (add a describing word). **4. Edit** – fix capitals, periods and spelling. **5. Publish** – write it neatly and share it.\n\nToday you write **3–4 sentences** about you. Use the frames: *My name is ___. I am ___ years old. I have ___. I like ___.*","examples":["Plan: Noura draws herself and writes labels: **hair**, **eyes**, **hands**.","Plan: Sami writes his ideas: Sami – 8 – black hair – books, moon.","Draft: **My name is Sami.**","Draft: **I am eight years old.**","Revise: *I have hair.* → **I have short black hair.**","Revise: *I like books.* → **I like books and the moon.**","Edit: *i like books* → **I like books.**","Edit: *my friend is omar.* → **My friend is Omar.**","Publish: Sami writes neatly on a star card and reads it to the class."],"common_errors":["✗ My name Sami. → ✓ My name is Sami. (In Arabic we say اسمي سامي without a verb; English needs **is**.)","✗ I nine years old. → ✓ I am nine years old. (English needs **am** after I.)","✗ I am like books. → ✓ I like books. (Do not use **am** with like.)","✗ I happy. → ✓ I am happy. (Use **am** before a feeling word.)","✗ My hair is long and black hair. → ✓ My hair is long and black. (Do not say **hair** two times.)","✗ I have a big eyes. → ✓ I have big eyes. (Do not use **a** with more than one thing.)"],"arabic":"الكاتب الجيد يتبع خمس خطوات تُسمّى مراحل الكتابة:\n\n1- خطِّط: فكِّر وارسم. 2- اكتب المسودة. 3- حسِّن: أضف كلمة وصفية. 4- دقِّق: صحِّح الحروف الكبيرة والنقاط والإملاء. 5- انشر: اكتب بخط جميل وشارك كتابتك.\n\nانتبه: في العربية نقول \"اسمي سامي\" دون فعل، أما في الإنجليزية فنقول My name is Sami، ونقول I am nine years old."},"video":{"script":[{"time":"00:00–00:15","narration":"Noura is a writer. Today you are a writer too!","on_screen":"I am a writer!","visual":"Noura opens her notebook; a gold star sticker says 'Writer' (as a picture, no text in art)."},{"time":"00:15–00:45","narration":"Step one: plan. Draw yourself. Add labels: hair, eyes, hands.","on_screen":"1 Plan ✏️","visual":"Noura draws a quick self-portrait and adds three labels with arrows."},{"time":"00:45–01:15","narration":"Step two: draft. My name is Noura. I am nine years old. I have long hair. I like to draw.","on_screen":"2 Draft","visual":"Sentences appear one by one on lined paper, each from a frame."},{"time":"01:15–01:40","narration":"Step three: revise. Make it better! I have long hair… I have long black hair!","on_screen":"3 Revise ➕","visual":"The word 'black' slides into the sentence with a sparkle."},{"time":"01:40–02:10","narration":"Step four: edit. Check: a capital letter at the start? A period at the end? Yes!","on_screen":"4 Edit ✔","visual":"Green and red checks appear at the start and end of each sentence."},{"time":"02:10–02:35","narration":"Step five: publish. Write it neatly and share it with a friend.","on_screen":"5 Publish 🌟","visual":"Noura pins her star card on an 'All About Us' wall next to Sami's card."},{"time":"02:35–02:50","narration":"Plan, draft, revise, edit, publish. Now it's your turn!","on_screen":"Your turn!","visual":"Five step icons light up in a row; Saqr gives a wing-thumbs-up."}],"captions_ar":["نورة كاتبة. واليوم أنت كاتب أيضًا!","الخطوة الأولى: خطِّط. ارسم نفسك وأضف بطاقات: الشعر، العينان، اليدان.","الخطوة الثانية: المسودة. اسمي نورة. عمري تسع سنوات. شعري طويل. أحب الرسم.","الخطوة الثالثة: حسِّن كتابتك. شعري طويل… شعري أسود طويل!","الخطوة الرابعة: دقِّق. هل يوجد حرف كبير في البداية؟ هل توجد نقطة في النهاية؟ نعم!","الخطوة الخامسة: انشر. اكتب بخط جميل وشارك صديقك.","خطِّط، اكتب، حسِّن، دقِّق، انشر. والآن دورك!"],"voice":"Narrator: American English, warm female teacher, speed 0.8. Noura: calm, encouraging 9-year-old girl voice. Gentle music bed (no singing), low volume."},"texts":[],"activities":[{"id":"RW-L01-U1-LS5-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the word to complete the sentence frame.","instructions_ar":"اختر الكلمة التي تكمل إطار الجملة.","items":[{"q":"My name ___ Reem.","answer":"is","explanation":"With *my name*, use *is*.","explanation_ar":"مع my name نستخدم is.","options":["is","am","are","be"],"dok":1,"skill":"sentence frames","stage":"controlled"},{"q":"I ___ nine years old.","answer":"am","explanation":"With *I*, use *am*.","explanation_ar":"مع I نستخدم am.","options":["is","are","have","am"],"dok":1,"skill":"sentence frames","stage":"controlled"},{"q":"I ___ long hair.","answer":"have","explanation":"We say *I have* + hair/eyes.","explanation_ar":"نقول I have للشعر والعينين.","options":["am","is","are","have"],"dok":1,"skill":"sentence frames","stage":"controlled"},{"q":"I ___ dates and milk.","answer":"like","explanation":"Use *like* for things you enjoy.","explanation_ar":"نستخدم like للأشياء التي نحبها.","options":["am","like","is","are"],"dok":1,"skill":"sentence frames","stage":"controlled"},{"q":"I am ___. I smile a lot.","answer":"happy","explanation":"A feeling word goes after *I am*.","explanation_ar":"بعد I am نضع كلمة شعور.","options":["hair","happy","hands","school"],"dok":1,"skill":"describing words","stage":"controlled"},{"q":"Which step comes first in the writing process?","answer":"plan","explanation":"First we plan.","explanation_ar":"أولًا نخطط.","options":["publish","edit","plan","revise"],"dok":1,"skill":"writing process","stage":"controlled"}]},{"id":"RW-L01-U1-LS5-A2","type":"sequence","stage":"guided","instructions":"Put in order: Put the words in order to make a sentence. Remember the capital letter and the period.","instructions_ar":"رتّب الكلمات لتكوّن جملة، وتذكّر الحرف الكبير والنقطة.","items":[{"q":"Build Sara's name sentence.","answer":"My name is Sara.","explanation":"Name sentence: My name is Sara.","explanation_ar":"جملة الاسم: My name is Sara.","stage":"guided","parts":["is","My","name","Sara."],"target":["My","name","is","Sara."]},{"q":"Build a sentence about being seven.","answer":"I am seven years old.","explanation":"Age sentence: I am seven years old.","explanation_ar":"جملة العمر.","stage":"guided","parts":["am","seven","years","I","old."],"target":["I","am","seven","years","old."]},{"q":"Build a sentence about brown eyes.","answer":"I have brown eyes.","explanation":"I have + describing word + eyes.","explanation_ar":"I have ثم الصفة ثم الاسم.","stage":"guided","parts":["brown","have","eyes.","I"],"target":["I","have","brown","eyes."]},{"q":"Build a sentence about liking school.","answer":"I like my school.","explanation":"I like + thing.","explanation_ar":"I like ثم الشيء.","stage":"guided","parts":["my","like","I","school."],"target":["I","like","my","school."]},{"q":"Build a sentence about a friend called Badr.","answer":"My friend is Badr.","explanation":"My friend is + name.","explanation_ar":"My friend is ثم الاسم.","stage":"guided","parts":["is","My","Badr.","friend"],"target":["My","friend","is","Badr."]},{"q":"Build a sentence about Hamad.","answer":"Hamad is a happy boy.","explanation":"Name + is + a + describing word + boy.","explanation_ar":"الاسم ثم is ثم a ثم الصفة ثم boy.","stage":"guided","parts":["happy","boy.","Hamad","is","a"],"target":["Hamad","is","a","happy","boy."]}]},{"id":"RW-L01-U1-LS5-A3","type":"open","stage":"freer","instructions":"Freer practice: Revise! Make each sentence better with a describing word.","instructions_ar":"حسِّن كل جملة بإضافة كلمة وصفية.","items":[{"q":"I have hair. → I have ______ hair.","answer":"I have short hair.","explanation":"Any describing word: long, short, black, brown.","explanation_ar":"أي كلمة وصفية مناسبة.","dok":2,"skill":"revising","stage":"freer"},{"q":"I have eyes. → I have ______ eyes.","answer":"I have big brown eyes.","explanation":"A color or size word.","explanation_ar":"كلمة لون أو حجم.","dok":2,"skill":"revising","stage":"freer"},{"q":"My school is ______.","answer":"My school is big.","explanation":"big / small / new.","explanation_ar":"كبيرة / صغيرة / جديدة.","dok":2,"skill":"revising","stage":"freer"},{"q":"I am a student. → I am a ______ student.","answer":"I am a happy student.","explanation":"happy / tall / new.","explanation_ar":"سعيد / طويل / جديد.","dok":2,"skill":"revising","stage":"freer"}]},{"id":"RW-L01-U1-LS5-A4","type":"writing","stage":"production","instructions":"Writing: Write your 3–4 sentences. Then edit with the checklist and publish.","instructions_ar":"اكتب جملك الثلاث أو الأربع، ثم دقّقها بالقائمة وانشرها.","items":[{"q":"Write your name sentence and your age sentence.","answer":"My name is Ali. I am nine years old.","explanation":"Two correct sentences.","explanation_ar":"جملتان صحيحتان.","dok":1,"skill":"writing","stage":"production"},{"q":"Write a sentence about how you look.","answer":"I have short black hair and brown eyes.","explanation":"I have + describing words.","explanation_ar":"I have مع كلمات وصفية.","dok":2,"skill":"writing","stage":"production"},{"q":"Write a sentence about what you like.","answer":"I like football and dates.","explanation":"I like + things.","explanation_ar":"I like مع الأشياء.","dok":2,"skill":"writing","stage":"production"},{"q":"Share with a partner. What did your partner like about your writing?","answer":"He liked 'brown eyes'.","explanation":"One positive comment.","explanation_ar":"تعليق إيجابي واحد.","dok":2,"skill":"sharing","stage":"production","_w":{"checklist":[],"min":null,"max":null}}]},{"id":"RW-L01-U1-LS5-ORG","type":"organizer","organizer":"Me Map (plan)","instructions":"Organizer: Draw yourself in the middle. Write one idea in each box.","items":[{"q":"My name","answer":"Ali"},{"q":"My age","answer":"9"},{"q":"How I look (hair, eyes)","answer":"short black hair, brown eyes"},{"q":"What I like","answer":"football, dates"}]},{"id":"RW-L01-U1-LS5-WR","type":"writing","instructions":"Writing: Write 3–4 sentences about you. Draw a picture of yourself and add labels. Write 3–4 sentences about you. Draw a picture of yourself and add labels.","instructions_ar":"اكتب 3–4 جمل عن نفسك، وارسم صورتك وأضف إليها بطاقات.","prompt":"Write 3–4 sentences about you. Draw a picture of yourself and add labels.","checklist":["My sentences begin with a capital letter.","My sentences end with a period.","I wrote I with a capital letter.","Names and places begin with a capital letter.","I used one describing word.","I left spaces between my words."],"rubric_id":"RW-RUBRIC-5T","min_words":12,"max_words":45,"organizer":"Me Map (name – age – how I look – what I like)","items":[{"q":"Write 3–4 sentences about you. Draw a picture of yourself and add labels.","answer":"My name is Ali. I am nine years old. I have short black hair and brown eyes. I like football and dates.","_w":{"checklist":["My sentences begin with a capital letter.","My sentences end with a period.","I wrote I with a capital letter.","Names and places begin with a capital letter.","I used one describing word.","I left spaces between my words."],"min":12,"max":45}}]}],"game":{"name":"Sentence Builder Relay","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Word builder: word tiles are scrambled; the child drags them into order on a sentence line. The capital letter tile glows green at the start and the period tile red at the end. Correct = the sentence is read aloud. 6 sentences, 20 seconds each.","Teams of four line up. Each team gets 6 envelopes.","Player 1 opens an envelope and builds the sentence on the desk.","The team reads the sentence aloud together; the teacher checks it.","If correct, Player 2 opens the next envelope; if not, the team fixes it first.","The first team to build all 6 sentences correctly wins."],"data":[]},"exit_quiz":[{"q":"What do we do in the *plan* step?","answer":"think and draw","explanation":"Planning is thinking and drawing ideas.","explanation_ar":"التخطيط يعني التفكير والرسم.","options":["share with the class","fix the periods","think and draw","copy neatly"],"dok":1,"skill":"writing process"},{"q":"Which step comes last?","answer":"publish","explanation":"Publish is the last step.","explanation_ar":"النشر هو الخطوة الأخيرة.","options":["plan","draft","publish","revise"],"dok":1,"skill":"writing process"},{"q":"In the *edit* step, we ___.","answer":"fix capitals and periods","explanation":"Editing means fixing mistakes.","explanation_ar":"التدقيق يعني تصحيح الأخطاء.","options":["fix capitals and periods","draw a picture","choose a friend","read a poem"],"dok":1,"skill":"writing process"},{"q":"Which sentence is better?","answer":"I have long black hair.","explanation":"It has describing words and a correct frame.","explanation_ar":"فيها كلمات وصفية وإطار صحيح.","options":["I have hair.","I hair long.","I am have hair.","I have long black hair."],"dok":2,"skill":"revising"},{"q":"Choose the correct sentence.","answer":"My name is Turki.","explanation":"We say *My name is…*","explanation_ar":"نقول My name is.","options":["My name is Turki.","My name Turki.","My name are Turki.","Me name is Turki."],"dok":1,"skill":"sentence frames"},{"q":"What is a *title*?","answer":"the name of a piece of writing","explanation":"A title is the name of the writing.","explanation_ar":"العنوان اسم القطعة المكتوبة.","options":["the name of a piece of writing","a big picture","the last sentence","a kind of pencil"],"dok":1,"skill":"vocabulary"},{"q":"Which word can describe hair?","answer":"long","explanation":"Long tells us about hair.","explanation_ar":"long تصف الشعر.","options":["like","school","long","age"],"dok":1,"skill":"describing words"},{"q":"Fahad writes *i like milk*. What must he fix?","answer":"a capital I and a period","explanation":"I is always capital and a sentence ends with a period.","explanation_ar":"يحتاج I كبيرة ونقطة.","options":["a new title","a picture","the word milk","a capital I and a period"],"dok":2,"skill":"editing"},{"q":"Why do writers *revise*?","answer":"to make the writing better","explanation":"Revise means make it better.","explanation_ar":"نحسّن الكتابة لتصبح أفضل.","options":["to start a new story","to make the writing better","to stop writing","to make it shorter"],"dok":2,"skill":"writing process"},{"q":"Which is the best sentence for an *All About Me* card?","answer":"I am nine and I like books.","explanation":"It tells about ME.","explanation_ar":"هذه الجملة تتحدث عني.","options":["The camel is big.","I am nine and I like books.","Omar likes football.","Close your eyes."],"dok":3,"skill":"purpose"}],"images":[{"id":"IMG-RW-L01-U1-LS5-V01","prompt":"Picture for the word 'plan': a child thinking with a light bulb above a blank page"},{"id":"IMG-RW-L01-U1-LS5-V02","prompt":"Picture for the word 'draw': a girl drawing a cat with a pencil"},{"id":"IMG-RW-L01-U1-LS5-V03","prompt":"Picture for the word 'write': a hand writing on lined paper"},{"id":"IMG-RW-L01-U1-LS5-V04","prompt":"Picture for the word 'check': a child looking at a page with a magnifying glass and a tick"},{"id":"IMG-RW-L01-U1-LS5-V05","prompt":"Picture for the word 'share': two children showing their papers to each other"},{"id":"IMG-RW-L01-U1-LS5-V06","prompt":"Picture for the word 'title': the top of a page with a highlighted heading line"},{"id":"IMG-RW-L01-U1-LS5-V07","prompt":"Picture for the word 'picture': a framed drawing of a family"},{"id":"IMG-RW-L01-U1-LS5-01","prompt":"Five icons showing the writing steps from plan to publish."},{"id":"IMG-RW-L01-U1-LS5-02","prompt":"A class wall with star-shaped cards made by children."},{"id":"IMG-RW-L01-U1-LS5-03","prompt":"A planning page with a child outline and four boxes."}],"audio":[{"id":"AUD-RW-L01-U1-LS5-V01","script":"plan. We plan our writing first."},{"id":"AUD-RW-L01-U1-LS5-V02","script":"draw. Layla can draw a cat."},{"id":"AUD-RW-L01-U1-LS5-V03","script":"write. Please write your name here."},{"id":"AUD-RW-L01-U1-LS5-V04","script":"check. Check your spelling."},{"id":"AUD-RW-L01-U1-LS5-V05","script":"share. We share our stories with the class."},{"id":"AUD-RW-L01-U1-LS5-V06","script":"title. The title of my story is \"Me\"."},{"id":"AUD-RW-L01-U1-LS5-V07","script":"picture. This picture shows my family."},{"id":"AUD-RW-L01-U1-LS5-VID","script":"Noura is a writer. Today you are a writer too! Step one: plan. Draw yourself. Add labels: hair, eyes, hands. Step two: draft. My name is Noura. I am nine years old. I have long hair. I like to draw. Step three: revise. Make it better! I have long hair… I have long black hair! Step four: edit. Check: a capital letter at the start? A period at the end? Yes! Step five: publish. Write it neatly and share it with a friend. Plan, draft, revise, edit, publish. Now it's your turn!"}]}],"unit_test":[{"q":"You hold a pencil with your ___.","answer":"hand","explanation":"We hold things with our hands.","explanation_ar":"نمسك الأشياء بأيدينا.","options":["eye","hair","hand","age"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"Badr is ten. His ___ is ten.","answer":"age","explanation":"Age tells how old you are.","explanation_ar":"العمر يدل على عدد السنوات.","options":["age","name","school","friend"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"Reem is a ___. She has a sister.","answer":"girl","explanation":"Reem is a girl's name; we use *she*.","explanation_ar":"ريم اسم بنت.","options":["boy","hand","school","girl"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"An elephant is very ___.","answer":"big","explanation":"Elephants are very large.","explanation_ar":"الفيل كبير جدًا.","options":["small","happy","special","big"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"We play together every day. We are ___.","answer":"friends","explanation":"People who play together are friends.","explanation_ar":"من يلعبون معًا أصدقاء.","options":["eyes","friends","ages","names"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"Green is the color I like most. It is my ___ color.","answer":"favorite","explanation":"Favorite = the one you like most.","explanation_ar":"favorite تعني المفضل.","options":["special","favorite","small","happy"],"dok":2,"skill":"vocabulary","_part":"Part A – Words"},{"q":"My ___ is short and brown.","answer":"hair","explanation":"Hair can be short and brown.","explanation_ar":"الشعر يمكن أن يكون قصيرًا وبنيًا.","options":["hair","hand","school","age"],"dok":2,"skill":"vocabulary","_part":"Part A – Words"},{"q":"Saad laughs and jumps. He feels ___.","answer":"happy","explanation":"Laughing shows he feels good.","explanation_ar":"الضحك يدل على السعادة.","options":["small","tall","happy","short"],"dok":2,"skill":"vocabulary in context","_part":"Part A – Words"},{"q":"Which sentence has NO mistakes?","answer":"My brother is Saud.","explanation":"Capital M, capital S, period.","explanation_ar":"حرف كبير وبداية واسم ونقطة.","options":["my brother is Saud.","My brother is Saud.","My brother is saud.","My brother is Saud"],"dok":1,"skill":"conventions","_part":"Part D – Check the sentences"},{"q":"Which words need capital letters? *we go to madinah.*","answer":"we and madinah","explanation":"First word and the name of a place.","explanation_ar":"أول كلمة واسم المكان.","options":["we and madinah","go and to","only go","only to"],"dok":2,"skill":"conventions","_part":"Part D – Check the sentences"},{"q":"A picture shows a boy pointing to his nose with a line and a word. The word is a ___.","answer":"label","explanation":"A word joined by a line to a part is a label.","explanation_ar":"الكلمة المتصلة بخط بجزء من الصورة بطاقة.","options":["title","period","label","poem"],"dok":2,"skill":"text features","_part":"Part D – Check the sentences"},{"q":"*Majed sits in the class.* This answers which question?","answer":"Where does Majed sit?","explanation":"In the class is a place.","explanation_ar":"في الفصل مكان.","options":["Who is Adam?","What does Majed like?","How old is Majed?","Where does Majed sit?"],"dok":2,"skill":"question words","_part":"Part D – Check the sentences"},{"q":"Which sentence is the best start for writing about yourself?","answer":"My name is Khalid.","explanation":"It tells about the writer.","explanation_ar":"الجملة تتحدث عن الكاتب نفسه.","options":["Cats are small.","The sun is hot.","Omar has a ball.","My name is Khalid."],"dok":2,"skill":"purpose","_part":"Part D – Check the sentences"}],"unit_writing":{"task":"Write 3–4 sentences about a friend. Use capital letters and periods.","model":"My friend is Omar. He is nine years old. He is tall, and he has short black hair. He likes football.","marks":20}});
